window.MANARA_DATA = {"app":"manara","version":2,"tracks":[{"slug":"luma-itiqad","name":"لمعة الاعتقاد","description":"لمعة الاعتقاد بشرح الشيخ عبدالرزاق البدر - 15 درسا مرئيا من السلسلة الرسمية على اليوتيوب، درس لكل فيديو.","icon":"book","order":1,"courses":[{"id":"luma-badr-15","title":"لمعة الاعتقاد (عقيدة)","author":"المتن: ابن قدامة المقدسي · الشرح المرئي: الشيخ عبدالرزاق البدر","level":"BEGINNER","description":"السلسلة المرئية الكاملة 15 فيديو: من مقدمة الشارح إلى خاتم النبيين، كل درس بفيديوه الخاص.","about":"هذه الدورة تعتمد اعتمادا كاملا على الشرح المرئي لسلسلة اليوتيوب PL_SRzub3Wl-Q3dEASEFnqURn7f8pevIEL (15 مقطعا). كل درس يقابل فيديو واحدا بنفس عنوانه، مع المتن والشرح المستفاد والاختبار. المصدر الصوتي الرسمي 5/5 مدمج ضمن التقسيم المرئي. مصادر المتن: الشاملة shamela.ws/book/11366 (العثيمين/اللمعة) بأرقام الفقرات الأصلية، وموقع ابن جبرين ibn-jebreen.com، وأرشيف archive.org/details/eng_736. كل درس يحمل رقم الفقرة وشاهده.","coverColor":"#1E3A5F","order":1,"lockLessons":false,"lockUntilPrev":false,"lessons":[{"id":"lum-01","order":1,"title":"الدرس 1: مدخل أكاديمي إلى اللمعة - المصنف والعنوان والمصطلح","chapter":"المدخل","summary":"درس أكاديمي تأسيسي: التعريف بالمصنف والمتن، وتحليل عنوان الكتاب، وتأصيل مصطلح العقيدة، وبيان أثر الاعتقاد في العمل.","content":{"objectives":["أن يترجم للمصنف ترجمة علمية موجزة ويبين منزلته.","أن يحلل عنوان الكتاب لفظا ومعنى: اللمعة، الاعتقاد، الهداية، الرشاد.","أن يؤصل مصطلح العقيدة لغة وشرعا ويرد دعوى حدوثه.","أن يبرهن على أثر الاعتقاد الصحيح في صلاح القلب والجوارح بالأدلة."],"matn":"نص المدخل من المتن:\n\nلمعة الاعتقاد الهادي إلى سبيل الرشاد - للإمام موفق الدين أبي محمد عبد الله بن أحمد بن محمد بن قدامة المقدسي.\n\n[١] الحمد لله المحمود بكل لسان، المعبود في كل زمان، الذي لا يخلو من علمه مكان... موصوف بما وصف به نفسه في كتابه وعلى لسان نبيه.\n\n[المصدر: الشاملة 11366/23]","briefExplanation":"هذا مدخل أكاديمي يبني الأساس: من هو ابن قدامة، ولماذا اللمعة، وماذا تعني ألفاظ العنوان، وهل العقيدة لفظ شرعي، وكيف يهدي الاعتقاد صاحبه.","detailedExplanation":"## أولا: التعريف بالمصنف والمتن\n\nالمصنف هو الإمام موفق الدين عبد الله بن أحمد بن قدامة المقدسي (541-620هـ)، من أئمة الحنابلة، جمع بين الفقه والأصول والاعتقاد. من أشهر مصنفاته: المغني في الفقه، وروضة الناظر في الأصول، والعمدة في الفقه، واللمعة في الاعتقاد.\n\nامتازت اللمعة بالوجازة مع الجمع لأصول معتقد أهل السنة: الصفات والقدر والإيمان واليوم الآخر والصحابة. ولذا اعتمدها العلماء للحفظ والتدريس، وشرحها غير واحد منهم.\n\n## ثانيا: تحليل العنوان\n\nاللمعة في اللغة: الضياء والوضاءة والحسن. وسمي بها المختصر لكونه قطعة مضيئة من العلم يكتفى بها المبتدئ.\n\nوالنكتة التربوية: الاعتقاد الصحيح نور يقذف في القلب فيبدد ظلمات الشك والحيرة، ويورث طمأنينة اليقين.\n\nالهادي إلى سبيل الرشاد: وصف للمتن بأثره، فمن ضبطه اهتدى. والسبيل هو الطريق الموصل، والرشاد هو الصلاح والاستقامة.\n\n## ثالثا: الهداية والرشاد وأثر القلب\n\nالهداية عند الاقتران يراد بها صلاح العلم: المعرفة والفهم والرسوخ. والرشاد يراد به صلاح العمل: الاستقامة والتوفيق والتطبيق. فالعلم الصحيح في القلب يثمر عملا صالحا في الجوارح.\n\nوالدليل الجامع حديث: إن في الجسد مضغة إذا صلحت صلح الجسد كله وإذا فسدت فسد الجسد كله ألا وهي القلب. متفق عليه. فالقلب ملك الجوارح، وصلاح المعتقد صلاح للملك فيصلح الجند.\n\n## رابعا: تأصيل مصطلح العقيدة\n\nالعقيدة والاعتقاد والمعتقد ألفاظ شرعية مأثورة، لا محدثة. ثبت في السنة: لا يعتقد قلب مسلم على ثلاث خصال إلا دخل الجنة: إخلاص العمل لله والنصيحة لولاة الأمر ولزوم الجماعة. رواه الدارمي. واستعملها السلف في تسمية مصنفاتهم.\n\nلغة: العقد هو الشد والربط الجازم. وشرعا: اليقين الجازم الذي لا يتخلله شك. قال تعالى: إنما المؤمنون الذين آمنوا بالله ورسوله ثم لم يرتابوا. فمن خالط قلبه شك في الأصول لم يكن اعتقاده عقيدة كاملة.\n\n## خلاصة الدرس\n\nمن عرف المصنف وثق بالمتن، ومن فهم العنوان أحب دراسته، ومن أدرك أن العقيدة يقين يهدي القلب علم الهداية وأثمر الرشاد في العمل.","evidences":[{"type":"sunnah","text":"ألا وإن في الجسد مضغة إذا صلحت صلح الجسد كله وإذا فسدت فسد الجسد كله ألا وهي القلب","reference":"متفق عليه"},{"type":"sunnah","text":"لا يعتقد قلب مسلم على ثلاث خصال إلا دخل الجنة: إخلاص العمل لله والنصيحة لولاة الأمر ولزوم الجماعة","reference":"سنن الدارمي"},{"type":"quran","text":"إنما المؤمنون الذين آمنوا بالله ورسوله ثم لم يرتابوا","reference":"سورة الحجرات: 15"},{"type":"quran","text":"ليس كمثله شيء وهو السميع البصير","reference":"سورة الشورى: 11"}],"scholars":[],"benefits":["معرفة المصنف طريق الثقة بالمتن.","الوجازة الجامعة ميزة المتون الأولى.","الاعتقاد نور يبدد الشك.","صلاح القلب يصلح الجوارح.","الهداية علم والرشاد عمل.","العقيدة لفظ شرعي ومعناها يقين بلا ريب."],"terms":[{"term":"اللمعة","definition":"الضياء والحسن، والمختصر المضيء من العلم."},{"term":"الهداية","definition":"صلاح العلم ورسوخه معرفة وفهما."},{"term":"الرشاد","definition":"صلاح العمل والاستقامة والتوفيق."},{"term":"العقيدة","definition":"الربط الجازم واليقين الذي لا ريب فيه."}],"mindMap":{"title":"مدخل اللمعة الأكاديمي","branches":[{"title":"المصنف والمتن","items":["ابن قدامة 541-620","الوجازة الجامعة","للحفظ والتدريس"]},{"title":"العنوان","items":["اللمعة ضياء","هاد للجوارح","سبيل الرشاد"]},{"title":"القلب والعمل","items":["القلب ملك","حديث المضغة","علم يثمر عملا"]},{"title":"المصطلح","items":["لفظ شرعي","العقد الربط","يقين بلا ريب"]}]},"summaryTable":{"headers":["المفهوم","التعريف","الدليل"],"rows":[["اللمعة","المختصر المضيء","لغة واصطلاحا"],["الهداية","صلاح العلم","المعرفة والفهم"],["الرشاد","صلاح العمل","الاستقامة"],["العقيدة","يقين بلا ريب","لم يرتابوا"]]},"video":{"url":"https://www.youtube.com/watch?v=Y2vTwtxlT58&list=PL_SRzub3Wl-Q3dEASEFnqURn7f8pevIEL","title":"١- مقدمة الشارح: فضيلة الشيخ عبدالرزاق البدر حفظه الله"}},"questions":[{"q":"من مصنف اللمعة؟","options":["ابن تيمية","ابن قدامة المقدسي","الطحاوي","مالك"],"answer":1},{"q":"ما ميزة المتن؟","options":["الطول","الوجازة مع جمع الأصول","الشعر","القصص"],"answer":1},{"q":"ما أقرب معاني اللمعة؟","options":["الظلمة","الضياء والحسن","الحجر","الماء"],"answer":1},{"q":"ما الدليل على أثر القلب؟","options":["حديث المضغة","آية الدين","حديث الصوم","لا دليل"],"answer":0},{"q":"ما الفرق بين الهداية والرشاد؟","options":["لا فرق","الهداية صلاح العلم والرشاد صلاح العمل","عكسهما","كلاهما مال"],"answer":1},{"q":"هل لفظ العقيدة شرعي؟","options":["نعم ثبت بالسنة واستعمال السلف","لا محدث مردود","خاص بالفلسفة","لا أصل له"],"answer":0},{"q":"متى يخرج الإيمان عن العقيدة؟","options":["عند اليقين","عند الريب والشك","عند العمل","عند النوم"],"answer":1}]},{"id":"lum-02","order":2,"title":"الدرس 2: ترجمة الإمام ابن قدامة - المولد والمكانة والأخلاق والصحبة","chapter":"المدخل","summary":"درس أكاديمي: نسب ابن قدامة ومولده ووفاته، مكانته وثماره الفقهية المتدرجة، أدبه وحلمه في المناظرة، وزمالته لعبد الغني وأثر الصحبة الصالحة.","content":{"objectives":["أن يذكر نسب ابن قدامة ومولده ووفاته ونشأته.","أن يبين مكانته العلمية وتدرجه الفقهي من العمدة إلى المغني.","أن يصف أخلاقه وحلمه وابتسامته في المناظرة.","أن يشرح زمالته لعبد الغني وفائدة القرين الصالح لطالب العلم."],"matn":"ترجمة صاحب المتن من كتب التراجم:\n\nهو الإمام موفق الدين أبو محمد عبد الله بن أحمد بن محمد بن قدامة المقدسي الدمشقي الصالحي الحنبلي. ولد بجماعيل من قرى نابلس سنة 541هـ، وتوفي يوم عيد الفطر سنة 620هـ. نشأ في بيت علم وهمة وحفظ للأوقات.\n\n[المصدر: سير أعلام النبلاء للذهبي + تفريغ المحاضرة الثانية - أكاديمي بلا توقيت]","briefExplanation":"ترجمة علمية جامعة: النسب والمولد، الثناء والمؤلفات المتدرجة، الخلق والمناظرة بابتسامة، والصحبة الصالحة مع ابن خالته عبد الغني.","detailedExplanation":"## أولا: المولد والنشأة\n\nنسبه: عبد الله بن أحمد بن محمد بن قدامة المقدسي الحنبلي. ولد بقرية جماعيل من قرى نابلس بفلسطين في شعبان سنة 541هـ، وتوفي يوم عيد الفطر سنة 620هـ.\n\nنشأ في بيت علم وأدب وهمة عالية، عرف بحفظ الأوقات وعلو الهمة في الطلب والرحلة إلى بغداد ودمشق.\n\n## ثانيا: المكانة العلمية والمؤلفات\n\nقال فيه شيخ الإسلام ابن تيمية: ما دخل الشام بعد الأوزاعي أفضل من الشيخ الموفق. وهو إمام الحنابلة في الفقه والأصول والاعتقاد.\n\nتميز بتأليف سلسلة فقهية متدرجة: عمدة الفقه للمبتدئين، ثم المقنع والكافي للمتوسطين، ثم المغني موسوعته الكبرى في الفقه المقارن. وفي الاعتقاد: اللمعة، وفي الأصول: روضة الناظر.\n\n## ثالثا: الأخلاق والمناظرة\n\nكان سمحا جميل الأدب طيب المعاملة، حتى قيل: كان لا يكاد يراه أحد إلا أحبه. ولم يحفظ عنه أنه أوجع قلب طالب.\n\nوفي المناظرة نقل الضياء عنه: كان لا يناظر أحدا إلا وهو يبتسم. وعلق الذهبي في السير بأنها منزلة شريفة، إذ الغالب في المناظرات ثورة النفس وضيق الصدر، بينما كان يملك نفسه.\n\n## رابعا: الزمالة والصحبة الصالحة\n\nنشأ مع ابن خالته الحافظ عبد الغني المقدسي صاحب عمدة الأحكام، وارتحلا معا في الطلب. فاتجه ابن قدامة للفقه فصار إمامه، واتجه عبد الغني للحديث فبرز فيه. وهذا تكامل نافع.\n\nوالفائدة التربوية: حاجة الطالب إلى القرين الصالح الذي يشد أزره، قال تعالى: سنشد عضدك بأخيك. فالصحبة تعين على المواظبة والتحصيل.","evidences":[{"type":"athar","text":"ما دخل الشام بعد الأوزاعي أفضل من الشيخ الموفق","reference":"قول ابن تيمية في ابن قدامة"},{"type":"athar","text":"كان الموفق لا يناظر أحدا إلا وهو يبتسم","reference":"نقل الضياء المقدسي وتعليق الذهبي في السير"},{"type":"quran","text":"سنشد عضدك بأخيك","reference":"سورة القصص: 35 - في الصحبة المعينة"},{"type":"sunnah","text":"المرء على دين خليله فلينظر أحدكم من يخالل","reference":"رواه أبو داود والترمذي"}],"scholars":[],"benefits":["حفظ الأوقات وعلو الهمة أساس الإمامة.","التدرج في المتون من العمدة إلى المغني منهج ناجح.","حسن الخلق يحبب العلم وأهله.","الابتسامة وضبط النفس كمال في المناظرة.","القرين الصالح يشد الأزر في الطلب."],"terms":[{"term":"موفق الدين","definition":"لقب ابن قدامة لتوفيقه في العلم والعمل."},{"term":"العمدة والمغني","definition":"أول سلسلته الفقهية وآخرها الموسوعية."},{"term":"المناظرة","definition":"مجادلة الخصم لإظهار الحق بأدب."},{"term":"الصحبة","definition":"القرين المعين على الطلب والمواظبة."}],"mindMap":{"title":"ترجمة ابن قدامة","branches":[{"title":"المولد","items":["جماعيل 541","وفاة 620","بيت علم"]},{"title":"المكانة","items":["ثناء ابن تيمية","العمدة للمبتدئ","المغني الموسوعة"]},{"title":"الأخلاق","items":["سمح محبوب","يبتسم في المناظرة","تعليق الذهبي"]},{"title":"الصحبة","items":["عبد الغني","تكامل فقه وحديث","سنشد عضدك"]}]},"summaryTable":{"headers":["المحور","البيان","العبرة"],"rows":[["المولد","541-620 جماعيل دمشق","حفظ الوقت"],["المؤلفات","عمدة مقنع مغني","تدرج"],["الأخلاق","يبتسم في المناظرة","حلم"],["الصحبة","عبد الغني","قرين صالح"]]},"video":{"url":"https://www.youtube.com/watch?v=CMXskx13dfY&list=PL_SRzub3Wl-Q3dEASEFnqURn7f8pevIEL","title":"شرح لمعة الاعتقاد - ٢- ترجمة المؤلف: فضيلة الشيخ عبدالرزاق البدر حفظه الله"}},"questions":[{"q":"أين ولد ابن قدامة ومتى؟","options":["بغداد 401","جماعيل 541","دمشق 620","القاهرة 500"],"answer":1},{"q":"ماذا قال ابن تيمية فيه؟","options":["أفضل من دخل الشام بعد الأوزاعي","مبتدع","ضعيف","لا يعرفه"],"answer":0},{"q":"ما أول سلسلته الفقهية؟","options":["المغني","عمدة الفقه","الكافي","المقنع"],"answer":1},{"q":"ما أدبه في المناظرة؟","options":["الغضب","يبتسم ويملك نفسه","الصراخ","الهجر"],"answer":1},{"q":"من زميله في الطلب؟","options":["النووي","عبد الغني المقدسي","الذهبي","ابن حجر"],"answer":1},{"q":"ما آية الصحبة؟","options":["سنشد عضدك بأخيك","قل هو الله أحد","تبت يدا","الكوثر"],"answer":0}]},{"id":"lum-03","order":3,"title":"الدرس 3: شرح مقدمة المتن - الحمد والتنزيه والأسماء","chapter":"المقدمة","summary":"درس أكاديمي: قراءة مقدمة ابن قدامة وشرحها فقرة فقرة: براعة الاستهلال، معاني الحمد والعبودية والعلم والشأن، التنزيه، نفوذ الحكم، نفي التمثيل، وقاعدة آية الشورى.","content":{"objectives":["أن يقرأ مقدمة المتن قراءة صحيحة ويضبط ألفاظها.","أن يشرح براعة الاستهلال ودلالتها على مقصود الكتاب.","أن يثبت معاني الحمد والعبودية وإحاطة العلم ونفوذ الحكم.","أن يضبط قاعدة التنزيه والإثبات وتوقيفية باب الصفات."],"matn":"نص مقدمة المتن:\n\nبسم الله الرحمن الرحيم. الحمد لله المحمود بكل لسان، المعبود في كل زمان، الذي لا يخلو من علمه مكان، ولا يشغله شأن عن شأن. جل عن الأشباه والأنداد، وتنزه عن الصاحبة والأولاد، ونفذ حكمه في جميع العباد. لا تمثله العقول بالتفكير، ولا تتوهمه القلوب بالتصوير، {لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ الْبَصِيرُ}. له الأسماء الحسنى والصفات العلى؛ {الرَّحْمَنُ عَلَى الْعَرْشِ اسْتَوَى * لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَمَا بَيْنَهُمَا وَمَا تَحْتَ الثَّرَى * وَإِنْ تَجْهَرْ بِالْقَوْلِ فَإِنَّهُ يَعْلَمُ السِّرَّ وَأَخْفَى}، أحاط بكل شيء علما، وقهر كل مخلوق عزة وحكما، ووسع كل شيء رحمة وعلما، {يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلا يُحِيطُونَ بِهِ عِلْما}، موصوف بما وصف به نفسه في كتابه العظيم وعلى لسان نبيه الكريم.\n\n[المصدر: الشاملة 11366/23]","briefExplanation":"افتتح المصنف بالحمد المتضمن لمضمون الكتاب، ثم فصل الشيخ كل جملة بدليلها: تسبيح المخلوقات، معبود السماء والأرض، إحاطة العلم، الشأن اليومي، التنزيه، نفوذ الحكم الكوني، نفي التمثيل، وآية الشورى أصلا في الباب.","detailedExplanation":"## أولا: براعة الاستهلال\n\nبدأ المصنف بالحمد الدال على مضمون الكتاب ومقصوده. وبراعة الاستهلال تعني دلالة الافتتاح على فحوى الكتاب. فالحمد هنا خلاصة العقيدة: إثبات للكمال وتنزيه عن النقص.\n\n## ثانيا: المحمود بكل لسان\n\nالله محمود تسبح له السماوات السبع والأرض ومن فيهن، وإن من شيء إلا يسبح بحمده. فكل المخلوقات مسبحة خاضعة إلا عصاة الجن والإنس.\n\n## ثالثا: المعبود في كل زمان ومكان\n\nمعبود في السماء ومعبود في الأرض: وهو الذي في السماء إله وفي الأرض إله. أي معبود فيهما، وعبادته دائمة، وخلق الخلق لها.\n\n## رابعا: إحاطة العلم وعدم الشغل\n\nعلمه محيط بالمخلوقات، وخلقه لها دليل علمه: ألا يعلم من خلق وهو اللطيف الخبير. لتعلموا أن الله على كل شيء قدير وأن الله قد أحاط بكل شيء علما. لا تخفى عليه خافية.\n\nوأما الشأن: كل يوم هو في شأن؛ يحيي ويميت ويعز ويذل ويخفض ويرفع ويهدي ويضل. الأمر أمره والخلق خلقه، لا يشغله شأن عن شأن.\n\n## خامسا: التنزيه ونفوذ الحكم\n\nجل عن الأشباه: ليس كمثله شيء. وعن الأنداد: ولم يكن له كفوا أحد، فلا تجعلوا لله أندادا. وتنزه عن الصاحبة والولد: بديع السماوات والأرض أنى يكون له ولد، قل هو الله أحد الله الصمد لم يلد ولم يولد.\n\nونفذ حكمه في جميع العباد: ماض في حكمك. والمراد الحكم الكوني القدري: إنما أمره إذا أراد شيئا أن يقول له كن فيكون.\n\n## سادسا: نفي التمثيل وآية الشورى\n\nلا تمثله العقول بالتفكير ولا تتوهمه القلوب بالتصوير؛ فالله أكبر وأعظم من كل تصور. وآية ليس كمثله شيء وهو السميع البصير أصل الباب: نفي المثلية تنزيه، وإثبات السمع والبصر إثبات على ما يليق بلا تمثيل.\n\n## سابعا: الأسماء والعرش والعلم والتوقيف\n\nله الأسماء الحسنى البالغة الحسن والصفات العلى. جمع بين علو الذات: الرحمن على العرش استوى، وإحاطة العلم: وإن تجهر بالقول فإنه يعلم السر وأخفى. وأحاط وقهر ووسع، ولا يحيطون به علما. وباب الصفات توقيفي: نصف الله بما وصف به نفسه وبما وصفه به رسوله لا نتجاوز القرآن والحديث.","evidences":[{"type":"quran","text":"تسبح له السماوات السبع والأرض ومن فيهن وإن من شيء إلا يسبح بحمده","reference":"سورة الإسراء: 44"},{"type":"quran","text":"وهو الذي في السماء إله وفي الأرض إله","reference":"سورة الزخرف: 84"},{"type":"quran","text":"ألا يعلم من خلق وهو اللطيف الخبير","reference":"سورة الملك: 14"},{"type":"quran","text":"كل يوم هو في شأن","reference":"سورة الرحمن: 29"},{"type":"quran","text":"ليس كمثله شيء وهو السميع البصير","reference":"سورة الشورى: 11 - أصل الباب"},{"type":"quran","text":"ولم يكن له كفوا أحد","reference":"سورة الإخلاص: 4"}],"scholars":[],"benefits":["الافتتاح يكشف مقصود الكتاب.","كل المخلوقات مسبحة إلا العصاة.","الخلق دليل إحاطة العلم.","شؤونه قدرة وتدبير لا يشغله شأن.","التنزيه والإثبات قاعدة محكمة."],"terms":[{"term":"براعة الاستهلال","definition":"دلالة الافتتاح على مضمون الكتاب."},{"term":"المحمود بكل لسان","definition":"المسبح له كل شيء."},{"term":"الحكم الكوني","definition":"القضاء النافذ: كن فيكون."},{"term":"أصل الباب","definition":"آية الشورى الجامعة للنفي والإثبات."}],"mindMap":{"title":"شرح المقدمة","branches":[{"title":"الافتتاح","items":["الحمد","براعة الاستهلال","خلاصة الكتاب"]},{"title":"الإثبات","items":["التسبيح","العبودية","العلم والشأن"]},{"title":"التنزيه","items":["الأنداد","الصاحبة","نفوذ الحكم"]},{"title":"القاعدة","items":["نفي التمثيل","آية الشورى","باب توقيفي"]}]},"summaryTable":{"headers":["الفقرة","المعنى","الشاهد"],"rows":[["براعة الاستهلال","الحمد خلاصة الكتاب","الافتتاح دال"],["المحمود","تسبيح الخلق","تسبح له السماوات"],["المعبود","في السماء والأرض","في السماء إله"],["العلم","محيط شامل","أحاط بكل شيء"],["الشأن","تدبير يومي","كل يوم هو في شأن"],["التنزيه","لا كفؤ ولا ولد","لم يكن له كفوا"],["الحكم","كوني نافذ","ماض في حكمك"]]},"video":{"url":"https://www.youtube.com/watch?v=yZ5RjSGXAK4&list=PL_SRzub3Wl-Q3dEASEFnqURn7f8pevIEL","title":"شرح لمعة الاعتقاد - ٣- شرح ( المقدمة ) فضيلة الشيخ عبدالرزاق البدر حفظه الله"}},"questions":[{"q":"ما براعة الاستهلال؟","options":["طول المقدمة","دلالة الافتتاح على مضمون الكتاب","الزخرفة","الإيجاز فقط"],"answer":1},{"q":"من يسبح لله؟","options":["كل المخلوقات إلا العصاة","لا أحد","الملائكة فقط","الجماد فقط"],"answer":0},{"q":"ما معنى في السماء إله وفي الأرض إله؟","options":["إلهان","معبود فيهما","لا عبادة","خاص بالسماء"],"answer":1},{"q":"ما دليل إحاطة العلم بالخلق؟","options":["ألا يعلم من خلق","قل هو الله أحد","تبت يدا","الكوثر"],"answer":0},{"q":"ما المراد بنفوذ الحكم؟","options":["الشرعي فقط","الكوني القدري كن فيكون","لا حكم","حكم البشر"],"answer":1},{"q":"ما آية أصل الباب؟","options":["ليس كمثله شيء وهو السميع البصير","الحمد لله","قل أعوذ","عم"],"answer":0}]},{"id":"lum-04","order":4,"title":"الدرس 4: منهج السلف في التسليم والقبول - درس أكاديمي","chapter":"الصفات","summary":"درس أكاديمي: قاعدة التسليم، المسالك الأربعة الباطلة، نقد عبارة التفويض، والمحكم والمتشابه والوقف والوصل.","content":{"objectives":["استيعاب الأصل الشرعي للتعامل مع الصفات: التسليم والقبول.","التمييز بين المسالك المنحرفة: الرد والتأويل والتشبيه والتمثيل.","التحليل النقدي لعبارة ابن قدامة في التفويض.","تفكيك المتشابه والمحكم وتطبيقه على نصوص الصفات معنى وكيفية."],"matn":"قال الإمام ابن قدامة:\n\nوكل ما جاء في القرآن أو صح عن المصطفى عليه الصلاة والسلام من صفات الرحمن وجب الإيمان به وتلقيه بالتسليم والقبول، وترك التعرض له بالرد والتأويل والتشبيه والتمثيل. وما أشكل من ذلك وجب إثباته لفظا وترك التعرض لمعناه، ونرد علمه إلى قائله ونجعل عهدته على ناقله، اتباعا لطريق الراسخين: {والراسخون في العلم يقولون آمنا به كل من عند ربنا} [آل عمران: 7].\n\nوقال في ذم مبتغي التأويل: {فأما الذين في قلوبهم زيغ فيتبعون ما تشابه منه ابتغاء الفتنة وابتغاء تأويله}؛ فجعل ابتغاء التأويل علامة على الزيغ، ثم حجبهم بقوله: {وما يعلم تأويله إلا الله}.\n\n[المصدر: نص المستخدم + الشاملة 11366/26]","briefExplanation":"قاعدة التسليم تحكم الدين كله، والمسالك الأربعة تنافيها، وعبارة التفويض مرجوع عنها عند المحققين، والمعنى معلوم والكيفية مفوضة.","detailedExplanation":"## المحور الأول: قاعدة التسليم والقبول\n\nالأصل المنهجي ثلاثية: من الله الرسالة، وعلى الرسول البلاغ، وعلى العبد التسليم. الدليل: فلا وربك لا يؤمنون حتى يحكموك فيما شجر بينهم ثم لا يجدوا في أنفسهم حرجا مما قضيت ويسلموا تسليما [النساء: 65]. والتسليم جوهر الإيمان لا سلوك ظاهر فقط.\n\n## المحور الثاني: المسالك الأربعة الباطلة\n\nالرد: نفي الصفات وجحدها كالجهمية والمعتزلة. والتأويل المذموم: صرف اللفظ عن ظاهره بلا دليل فرارا من الإثبات فيقع في شر منه. والتشبيه: إثبات مع تشبيه الخالق بالمخلوق. والتمثيل: اعتقاد المثل التام. والقرآن استعمل التمثيل: ليس كمثله شيء [الشورى: 11]، فاستعماله أولى لأن نفي التشبيه بإطلاق قد يستغله أهل الكلام لنفي المعاني.\n\n## المحور الثالث: نقد عبارة التفويض\n\nقول المصنف: وما أشكل وجب إثباته لفظا وترك التعرض لمعناه. وجه المؤاخذة: ظاهره يوافق المفوضة وهو من شر المذاهب كما قرر ابن تيمية. وقد يلتمس محمل الإشكال النسبي لا المطلق، لكن السياق لا يساعد لأنه أوجب ترك المعنى مطلقا.\n\nومذهب السلف: معاني النصوص معلومة باللسان العربي وهي أشرف المعاني. وقولهم أمروها كما جاءت أي جاءت محملة بالمعاني فإمرارها إثبات اللفظ والمعنى ونفي الكيف. ومن أشكل عليه فالواجب التعلم ومراجعة الراسخين لا نفي المعنى.\n\n## المحور الرابع: المتشابه والتأويل والوقف والوصل\n\nنصوص الصفات محكمة المعنى لا متشابهة المعنى، والتشابه في الكيفية والحقيقة. ففي قوله وما يعلم تأويله إلا الله: عند الوقف المراد الحقيقة والكيفية لا يعلمها إلا الله. وعند الوصل: وما يعلم تأويله إلا الله والراسخون في العلم، المراد التفسير يعلمه الراسخون. وصح عن ابن عباس: أنا من الراسخين، وعرض مجاهد المصحف عليه يسأله عن كل آية.\n\n## خلاصة\n\nالواجب الإيمان الكامل والتسليم. والمنحرف أربعة. والتفويض المطلق مرجوع عنه. والمعنى معلوم والكيفية مجهولة.","evidences":[{"type":"quran","text":"والراسخون في العلم يقولون آمنا به كل من عند ربنا","reference":"سورة آل عمران: 7"},{"type":"quran","text":"فأما الذين في قلوبهم زيغ فيتبعون ما تشابه منه ابتغاء الفتنة وابتغاء تأويله","reference":"سورة آل عمران: 7"},{"type":"quran","text":"وما يعلم تأويله إلا الله","reference":"سورة آل عمران: 7"},{"type":"quran","text":"فلا وربك لا يؤمنون حتى يحكموك فيما شجر بينهم ثم لا يجدوا في أنفسهم حرجا مما قضيت ويسلموا تسليما","reference":"سورة النساء: 65"},{"type":"quran","text":"ليس كمثله شيء وهو السميع البصير","reference":"سورة الشورى: 11"}],"scholars":[],"benefits":["التسليم جوهر الإيمان.","المسالك الأربعة تنافي التسليم.","التفويض المطلق مرجوع عنه.","المعنى معلوم والكيفية مجهولة.","الوصل للمعنى والوقف للكيفية."],"terms":[{"term":"التسليم","definition":"الانقياد الكامل لمراد الله ورسوله."},{"term":"الرد","definition":"نفي الصفات وجحدها."},{"term":"التأويل المذموم","definition":"صرف اللفظ عن ظاهره بلا دليل."},{"term":"التفويض","definition":"ترك المعنى مطلقا وهو خطأ."}],"mindMap":{"title":"التسليم والقبول","branches":[{"title":"القاعدة","items":["من الله الرسالة","على الرسول البلاغ","علينا التسليم"]},{"title":"المسالك","items":["الرد إنكار","التأويل صرف","التمثيل نفيه أولى"]},{"title":"النقد","items":["عبارة مشكلة","المعنى معلوم","علاجها التعلم"]},{"title":"المتشابه","items":["المعنى محكم","الكيفية متشابهة","وصل ووصل"]}]},"summaryTable":{"headers":["المسلك","التعريف","الحكم"],"rows":[["الرد","نفي الصفات","جحد مناف للإيمان"],["التأويل","صرف بلا دليل","فرار إلى شر"],["التمثيل","إثبات المثل التام","منفي بنص الشورى"],["التفويض","ترك المعنى","مرجوع عنه"]]},"video":{"url":"https://www.youtube.com/watch?v=AxFpCgkdUVY&list=PL_SRzub3Wl-Q3dEASEFnqURn7f8pevIEL","title":"شرح لمعة الاعتقاد - ٤- شرح ( التسليم والقبول لآيات الصفات ) فضيلة الشيخ عبدالرزاق البدر حفظه الله"}},"questions":[{"q":"أي لفظ أولى في المعتقد ولماذا؟","options":["التشبيه لأنه أشهر","التمثيل لوروده في القرآن ليس كمثله شيء","التعطيل","لا فرق"],"answer":1},{"q":"ما معنى أمروها كما جاءت؟","options":["إثبات اللفظ وحده","إثبات اللفظ والمعنى ونفي الكيف","نفيهما معا","تأويلها"],"answer":1},{"q":"ما وجه المؤاخذة على عبارة التفويض؟","options":["أنها إثبات زائد","أن ظاهرها تفويض المعاني وهو مسلك المفوضة","أنها قصيرة","لا مؤاخذة"],"answer":1},{"q":"كيف يتغير معنى التأويل وقفا ووصلا؟","options":["الوقف للحقيقة والكيفية والوصل للتفسير يعلمه الراسخون","عكسهما","لا يتغير","كلاهما نفي"],"answer":0}]},{"id":"lum-05","order":5,"title":"الدرس 5: منهج أئمة السلف في الصفات - درس أكاديمي","chapter":"الصفات","summary":"درس أكاديمي: قاعدة الشافعي في المراد الشرعي، وإجماع الإقرار والإمرار والإثبات، وتحليل قول أحمد لا كيف ولا معنى.","content":{"objectives":["استيعاب قاعدة الشافعي في الانقياد للمراد الإلهي والنبوي.","فهم إجماع السلف على الإقرار والإمرار والإثبات.","تحليل قول أحمد لا كيف ولا معنى وتوجيه نفي المعنى.","تطبيق قاعدة إثبات بلا تمثيل وتنزيه بلا تعطيل."],"matn":"قال ابن قدامة:\n\nوقال الإمام أبو عبد الله محمد بن إدريس الشافعي: آمنت بالله وبما جاء عن الله على مراد الله، وآمنت برسول الله وبما جاء عن رسول الله على مراد رسول الله.\n\nوعلى هذا درج السلف وأئمة الخلف كلهم متفقون على الإقرار والإمرار والإثبات لما ورد من الصفات من غير تعرض لتأويله.\n\nوقال الإمام أحمد في أحاديث النزول والرؤية: نؤمن بها ونصدق بها لا كيف ولا معنى، ولا نرد منها شيئا، ونعلم أن ما جاء به الرسول حق، ولا نصف الله بأكثر مما وصف به نفسه بلا حد ولا غاية: {ليس كمثله شيء وهو السميع البصير} [الشورى: 11].\n\n[المصدر: نص المستخدم + الشاملة 11366/30]","briefExplanation":"قاعدة الشافعي تبطل التحكم العقلي، وإجماع الإقرار والإمرار والإثبات، وتحليل لا كيف نفي للتكييف ولا معنى نفي للمعاني المحدثة لا لأصل المعنى.","detailedExplanation":"## المحور الأول: قاعدة الشافعي\n\nآمنت بالله وبما جاء عن الله على مراد الله. فصحة الإيمان مشروطة بتلقي النص وفق مراد المرسل والمبلغ. ويبطل التحكم العقلي والذوقي وإسقاط التأويلات الكلامية التي تصرف النصوص إلى ما أراده المتكلمون لا ما أراده الله ورسوله. فالإيمان الحقيقي إيمان باللفظ والمعنى المقصود شرعا.\n\n## المحور الثاني: إجماع الإقرار والإمرار والإثبات\n\nاتفق السلف على ثلاثة أركان: الإقرار بالنصوص وعدم جحدها، والإمرار كما جاءت دون تحريف وتكييف، والإثبات للمعاني الحقيقية اللائقة. وجاءت النصوص بلغة عربية محملة بمدلولاتها، فإمرارها إثبات اللفظ والمعنى معا.\n\n## المحور الثالث: تحليل لا كيف ولا معنى\n\nلا كيف: قطع للتكييف والتمثيل وتفويض الكيفية إلى الله. ولا معنى: ليس نفيا لأصل المعنى اللغوي الشرعي، بل نفي للمعاني المحدثة المبتدعة كتأويل النزول بنزول الأمر، ونفي لمعنى التشبيه. فالنفي متوجه للمعنى المؤول الباطل.\n\nوختم أحمد بالضابط: لا نرد على رسول الله قبولا وانقيادا، ولا نصف الله بأكثر مما وصف به نفسه وقوفا عند النص، بلا حد ولا غاية تنزيها عملا بآية الشورى.\n\n## خلاصة\n\nالواجب الإيمان بمراد الله ورسوله، والسلف على إثبات المعنى ونفي الكيف، وقاعدة أهل السنة: إثبات بلا تمثيل وتنزيه بلا تعطيل.","evidences":[{"type":"athar","text":"آمنت بالله وبما جاء عن الله على مراد الله وآمنت برسول الله وبما جاء عن رسول الله على مراد رسول الله","reference":"قول الشافعي"},{"type":"athar","text":"نؤمن بها ونصدق بها لا كيف ولا معنى","reference":"قول أحمد في النزول والرؤية"},{"type":"quran","text":"ليس كمثله شيء وهو السميع البصير","reference":"سورة الشورى: 11"}],"scholars":[],"benefits":["المراد الشرعي حاكم لا العقل.","الإقرار والإمرار والإثبات منهج متكامل.","نفي الكيف قطع للتشبيه.","نفي المعنى المحدث لا أصل المعنى.","القاعدة الذهبية إثبات وتنزيه."],"terms":[{"term":"المراد الشرعي","definition":"ما قصده الله ورسوله بالنص."},{"term":"الإمرار","definition":"إبقاء النص بلفظه ومعناه كما ورد."},{"term":"لا كيف","definition":"نفي العلم بالكيفية."},{"term":"لا معنى","definition":"نفي المعاني المبتدعة لا أصل المعنى."}],"mindMap":{"title":"منهج السلف","branches":[{"title":"الشافعي","items":["على مراد الله","على مراد رسوله","إبطال التحكم"]},{"title":"الإجماع","items":["إقرار","إمرار","إثبات"]},{"title":"أحمد","items":["لا كيف","لا معنى محدث","بلا حد"]}]},"summaryTable":{"headers":["القاعدة","المعنى","الثمرة"],"rows":[["على مراد الله","اتباع لا ابتداع","صحة الإيمان"],["أمروها","لفظ ومعنى","قطع التأويل"],["لا كيف","نفي التكييف","تفويض الكيف"],["لا معنى","نفي المحدث","إثبات الأصل"]]},"video":{"url":"https://www.youtube.com/watch?v=9gVA1rSsAAA&list=PL_SRzub3Wl-Q3dEASEFnqURn7f8pevIEL","title":"شرح لمعة الاعتقاد - ٥- شرح ( كلام أئمة السلف في الصفات ) فضيلة الشيخ عبدالرزاق البدر حفظه الله"}},"questions":[{"q":"كيف تبطل مقولة الشافعي مسلك أهل التأويل؟","options":["بتحكيم العقل","بإيجاب الإيمان على مراد الله ورسوله لا مراد المتكلمين","بالسكوت","بالشعر"],"answer":1},{"q":"ما أركان منهج السلف الثلاثة؟","options":["التأويل والتعطيل والتمثيل","الإقرار والإمرار والإثبات","الشك والريب والظن","لا أركان"],"answer":1},{"q":"كيف وجه الشارح ولا معنى؟","options":["نفي أصل المعنى","نفي المعاني المحدثة لا أصل المعنى الشرعي","إثبات التشبيه","لا توجيه"],"answer":1},{"q":"ما شاهد تطبيق آية الشورى عند أحمد؟","options":["بلا حد ولا غاية مع ليس كمثله شيء","لا شاهد","نفي السمع","إثبات المثل"],"answer":0}]},{"id":"lum-06","order":6,"title":"الدرس 6: الاتباع والتحذير من الابتداع - درس أكاديمي","chapter":"المنهج","summary":"درس أكاديمي في أثر عمر بن عبد العزيز: الوقوف حيث وقف القوم، رد شبهة الجهل، البرهان المنطقي، والوسطية بين الجفاء والغلو.","content":{"objectives":["استيعاب أصل الاتباع بهدي الصحابة من أثر عمر.","تفكيك شبهة أن السلف كفوا لقلة علمهم.","تطبيق البرهان المنطقي لإبطال المحدثات.","تمييز الوسطية بين الجفاء والغلو."],"matn":"قال ابن قدامة:\n\nوقال عمر بن عبد العزيز في كلام له: قف حيث وقف القوم؛ فإنهم عن علم وقفوا وببصر نافذ كفوا، وهم كانوا على كشف الأمور أقوى، وبفضل ما هم فيه أولى، فإن كان الهدى ما أنتم عليه لقد سبقتموهم، ولئن قلتم حدث بعدهم فما أحدثه إلا من خالف هديهم ورغب عن سنتهم، ولقد وصفوا منه ما يكفي وتكلموا منه ما يشفي، فما دونهم مقصر ولا فوقهم محسر، ولقد قصر قوم دونهم فجفوا وطمح عنهم آخرون فغلوا، وإنهم بين ذلك لعلى هدى مستقيم.\n\n[المصدر: نص المستخدم + الشاملة]","briefExplanation":"قاعدة الوقوف، ورد الشبهة، والبرهان الحاصر، وقاعدة الوسطية.","detailedExplanation":"## المحور الأول: قاعدة الاتباع\n\nقف حيث وقف القوم أي الصحابة والتابعون. الالتزام بالحدود وعدم استحداث أصول لم يسبقوا إليها. والسلامة في الاقتفاء لمن شهد التنزيل.\n\n## المحور الثاني: رد الشبهة\n\nزعم المتكلمون أن السلف كفوا لقلة علم. والحق أنهم عن علم وقفوا وببصر نافذ كفوا. فعلم السلف إيماني من الوحي، وعلم المبتدع خوض وشبهات. فتركهم عن علم وبصيرة بحرمة التكلف.\n\n## المحور الثالث: البرهان المنطقي\n\nإما أن ما عليه المبتدعة هدى فيلزم سبقهم الصحابة وهو باطل، أو حدث بعدهم فيلزم أنه إحداث ممن خالف هديهم. والدين كمل: اليوم أكملت لكم دينكم. فكل محدث بعدهم مخالف ضلال.\n\n## المحور الرابع: الكفاية والوسطية\n\nوصفوا ما يكفي وتكلموا ما يشفي. فما دونهم مقصر جاف معطل، ولا فوقهم محسر غال متكلف. وهم على هدى مستقيم بين الجفاء والغلو.\n\n## خلاصة\n\nالوقوف واجب منج، وتركهم عن علم، والمحدث بعدهم بدعة، ومنهجهم وسط عدل.","evidences":[{"type":"quran","text":"اليوم أكملت لكم دينكم وأتممت عليكم نعمتي","reference":"سورة المائدة: 3"},{"type":"sunnah","text":"عليكم بسنتي وسنة الخلفاء الراشدين","reference":"رواه أبو داود"},{"type":"athar","text":"قف حيث وقف القوم فإنهم عن علم وقفوا وببصر نافذ كفوا","reference":"أثر عمر بن عبد العزيز"}],"scholars":[],"benefits":["الوقوف منجاة.","ترك السلف عن علم لا جهل.","المحدث بعدهم بدعة.","الوسطية بين الجفاء والغلو."],"terms":[{"term":"الوقف","definition":"لزوم حد السلف."},{"term":"البصر النافذ","definition":"البصيرة بعاقبة البدع."},{"term":"المحسر","definition":"المتجاوز المنهك بالتكلف."},{"term":"الوسطية","definition":"بين التعطيل والتمثيل."}],"mindMap":{"title":"الاتباع","branches":[{"title":"القاعدة","items":["قف حيث وقفوا","السلامة","الاقتفاء"]},{"title":"الشبهة","items":["عن علم","ببصر نافذ","لا عن جهل"]},{"title":"البرهان","items":["سبق أم إحداث","كلاهما باطل","الدين كمل"]},{"title":"الوسطية","items":["كاف شاف","دونهم جفاء","فوقهم غلو"]}]},"summaryTable":{"headers":["الانحراف","الوصف","الحكم"],"rows":[["الجفاء","ترك الإثبات","تقصير"],["السلف","كاف شاف","هدى مستقيم"],["الغلو","تكلف وتأويل","ابتداع"]]},"video":{"url":"https://www.youtube.com/watch?v=E5aqpEQz6To&list=PL_SRzub3Wl-Q3dEASEFnqURn7f8pevIEL","title":"شرح لمعة الاعتقاد - ٦- شرح ( الترغيب في السنة والتحذير من البدعة ) فضيلة الشيخ عبدالرزاق البدر حفظه الله"}},"questions":[{"q":"ماذا قصد بع عن علم وقفوا وببصر كفوا؟","options":["جهلهم","تركهم عن علم وبصيرة بحرمة التكلف","خوفهم","لا معنى"],"answer":1},{"q":"ما معنى فما دونهم مقصر ولا فوقهم محسر؟","options":["لا حد","التقصير جفاء والمجاوزة غلو","كلاهما حق","لا وسطية"],"answer":1},{"q":"صغ حجة إبطال المحدثات؟","options":["إما سبقوا الصحابة وهو باطل أو أحدثوا بعدهم فهو بدعة","لا حجة","البدعة حسنة","الصحابة جهلوا"],"answer":0},{"q":"كيف يخرج الطالب إلى الجفاء أو الغلو؟","options":["بلزوم النص","بترك الإثبات أو بالتكلف فيه","بالعمل","بالدعاء"],"answer":1}]},{"id":"lum-07","order":7,"title":"الدرس 7: آيات الصفات ذاتية وفعلية - درس أكاديمي","chapter":"الصفات","summary":"درس أكاديمي: تقسيم الصفات، الوجه واليدين والنفس، المجيء والإتيان ورد شبهة المضاف، وقاعدة الإضافة في الرضا والمحبة والغضب.","content":{"objectives":["التمييز بين الصفات الذاتية والفعلية.","فهم الوجه واليدين والنفس وإبطال التأويل.","استيعاب المجيء وتفكيك شبهة الأمر.","تطبيق قاعدة الإضافة على الرضا والمحبة والغضب."],"matn":"قال ابن قدامة:\n\nفمما جاء من آيات الصفات: {ويبقى وجه ربك ذو الجلال والإكرام} [الرحمن: 27]، {بل يداه مبسوطتان} [المائدة: 64]، {تعلم ما في نفسي ولا أعلم ما في نفسك} [المائدة: 116]، {وجاء ربك} [الفجر: 22]، {هل ينظرون إلا أن يأتيهم الله} [البقرة: 210]، {رضي الله عنهم ورضوا عنه} [المائدة: 119]، {يحبهم ويحبونه} [المائدة: 54]، {غضب الله عليهم} [الفتح: 6]، {اتبعوا ما أسخط الله} [محمد: 28]، {كره الله انبعاثهم} [التوبة: 46].\n\n[المصدر: نص المستخدم + الشاملة 11366/43]","briefExplanation":"الآيات على سبيل التمثيل: ذاتية ملازمة وفعلية بمشيئة، مع الأدلة اللغوية والردود.","detailedExplanation":"## التقسيم\n\nذاتية ملازمة لا تنفك: الوجه واليدان والنفس. وفعلية بمشيئة: المجيء والإتيان والرضا والمحبة والغضب والسخط والكره.\n\n## الوجه\n\nويبقى وجه ربك ذو الجلال. ذو بالرفع نعت للوجه لا للرب، فالوجه صفة قائمة بالذات. وفي الحديث: حجابه النور لو كشفه لأحرقت سبحات وجهه. ويثمر الشوق للنظر: أسألك لذة النظر إلى وجهك.\n\n## اليدان\n\nبل يداه مبسوطتان بصيغة التثنية، وأسند إليهما الخلق والقبض والبسط: لما خلقت بيدي. ودعوى النعمة أو القوة باطلة؛ فلا تثنى اليد بمعناهما ولا يخلق آدم بنعمتين. وفي الحديث: يمين الله ملأى.\n\n## النفس\n\nتعلم ما في نفسي ولا أعلم ما في نفسك. المراد عند الإطلاق الذات المتصفة بالكمال لا صفة زائدة كاليد.\n\n## المجيء والإتيان\n\nوجاء ربك، هل ينظرون إلا أن يأتيهم الله. ودعوى تقدير الأمر يبطلها المقابلة: هل ينظرون إلا أن تأتيهم الملائكة أو يأتي ربك أو يأتي بعض آيات ربك [الأنعام: 158]. ففرق بين مجيء الملائكة والآيات ومجيئه للفصل. ولو كان أمره لكان تكرارا.\n\n## الرضا والمحبة والغضب\n\nرضي الله عنهم، يحبهم ويحبونه، غضب الله عليهم، أسخط الله، كره الله. والقاعدة: الصفة بحسب الموصوف؛ ففي المخلوق بضعف، وفي الخالق بكمال بلا تمثيل: ليس كمثله شيء. وتأويل الغضب بإرادة الانتقام تعطيل.\n\n## خلاصة\n\nذاتية: الوجه واليدان والنفس. فعلية: المجيء والرضا والغضب. والإعراب حجة، والمقابلة تبطل التأويل، والإضافة تمنع التشبيه.","evidences":[{"type":"quran","text":"ويبقى وجه ربك ذو الجلال والإكرام","reference":"سورة الرحمن: 27"},{"type":"quran","text":"بل يداه مبسوطتان","reference":"سورة المائدة: 64"},{"type":"quran","text":"وجاء ربك","reference":"سورة الفجر: 22"},{"type":"quran","text":"هل ينظرون إلا أن تأتيهم الملائكة أو يأتي ربك أو يأتي بعض آيات ربك","reference":"سورة الأنعام: 158 - المقابلة"},{"type":"quran","text":"ليس كمثله شيء وهو السميع البصير","reference":"سورة الشورى: 11"}],"scholars":[],"benefits":["التقسيم يضبط الباب.","الإعراب حجة على الصفة.","المقابلة تبطل تقدير الأمر.","الإضافة تمنع التشبيه."],"terms":[{"term":"الذاتية","definition":"ملازمة لا تنفك."},{"term":"الفعلية","definition":"بمشيئة إن شاء فعل."},{"term":"المقابلة","definition":"العطف يقتضي المغايرة."},{"term":"الإضافة","definition":"الصفة بحسب الموصوف."}],"mindMap":{"title":"آيات الصفات","branches":[{"title":"ذاتية","items":["الوجه","اليدان","النفس"]},{"title":"فعلية","items":["المجيء","الرضا","الغضب"]},{"title":"الردود","items":["الإعراب","المقابلة","الإضافة"]}]},"summaryTable":{"headers":["الصفة","النوع","الدليل"],"rows":[["الوجه","ذاتية","ذو الجلال بالرفع"],["اليدان","ذاتية","مبسوطتان تثنية"],["المجيء","فعلية","يأتي ربك مقابل الملائكة"],["الرضا","فعلية","رضي الله عنهم"]]},"video":{"url":"https://www.youtube.com/watch?v=xyBx3V7-byo&list=PL_SRzub3Wl-Q3dEASEFnqURn7f8pevIEL","title":"شرح لمعة الاعتقاد - ٧- شرح ( ذكر بعض آيات الصفات ) فضيلة الشيخ عبدالرزاق البدر حفظه الله"}},"questions":[{"q":"كيف نستدل بإعراب ذو الجلال؟","options":["لا دلالة","بالرفع نعت للوجه فهو صفة قائمة","مضاف للرب","حذف"],"answer":1},{"q":"ما دلالة الإضافة والتخصيص؟","options":["المماثلة","الصفة بحسب الموصوف فلا مماثلة","نفي الصفة","لا قاعدة"],"answer":1},{"q":"كيف نرد تأويل وجاء ربك بأمره؟","options":["بالمقابلة في الأنعام بين إتيان الملائكة والرب والآيات","بالسكوت","بالشعر","لا رد"],"answer":0},{"q":"صنف الصفات المذكورة؟","options":["كلها فعلية","ذاتية الوجه واليدان والنفس وفعلية الباقي","كلها ذاتية","لا تقسيم"],"answer":1}]},{"id":"lum-08","order":8,"title":"الدرس 8: أحاديث الصفات والعلو والاستواء - درس أكاديمي","chapter":"الصفات","summary":"درس أكاديمي: حجية أحاديث النزول والعجب والضحك، وضوابط المتن، وأدلة العلو والاستواء، وقاعدة مالك بأركانها.","content":{"objectives":["استيعاب حجية أحاديث الصفات ودحض التأويل.","تطبيق ضوابط الإثبات بلا رد ولا تشبيه وقطع التخيل.","استقراء أدلة العلو والاستواء لغة وفطرة.","تحليل قاعدة مالك وتطبيقها على سائر الصفات."],"matn":"قال ابن قدامة:\n\nومن السنة: ينزل ربنا كل ليلة إلى سماء الدنيا، ويعجب ربك من شاب ليست له صبوة، ويضحك الله إلى رجلين يقتل أحدهما الآخر يدخلان الجنة. فهذا وما أشبهه مما صح سنده وعدلت رواته: نؤمن به ولا نرده ولا نجحده ولا نتأوله بتأويل يخالف ظاهره ولا نشبهه بصفات المخلوقين، ونعلم أن الله لا شبيه له: {ليس كمثله شيء وهو السميع البصير}. وكل ما تخيل في الذهن أو خطر بالبال فالله على خلافه.\n\nومن ذلك: {الرحمن على العرش استوى}، {أأمنتم من في السماء}. وقوله: ربنا الله الذي في السماء تقدس اسمك. وقوله للجارية: أين الله؟ قالت: في السماء. قال: أعتقها فإنها مؤمنة. وقوله لحصين: كم إلها تعبد... فاترك الستة واعبد الذي في السماء. وفوق ذلك العرش والله فوق ذلك. وسئل مالك: كيف استوى؟ فقال: الاستواء غير مجهول والكيف غير معقول والإيمان به واجب والسؤال عنه بدعة. ثم أمر بالرجل فأخرج.\n\n[المصدر: نص المستخدم + الشاملة 11366/53 وما بعدها]","briefExplanation":"السنة مصدر أصيل، والضوابط أربعة تمنع الرد والتأويل والتشبيه والتخيل، والعلو ثابت بالكتاب والسنة والفطرة، وقاعدة مالك ميزان الباب.","detailedExplanation":"## المحور الأول: أحاديث الصفات\n\nالنزول متواتر رواه أكثر من عشرين صحابيا: ينزل ربنا كل ليلة. ودعوى نزول أمره يبطلها التمام: فيقول من يدعوني فأستجيب له؛ فالأمر لا يقول ذلك. والعجب: يعجب ربك من شاب ليست له صبوة، وهو ثابت على وجه الكمال لا عن جهل بل لخروجه عن نظائره. والضحك: يضحك الله إلى رجلين، كافر يقتل مسلما ثم يسلم ويستشهد فيدخلان الجنة، سعة رحمة.\n\n## المحور الثاني: الضوابط\n\nنؤمن بلا رد ولا جحد، ولا نتأوله بتأويل يخالف ظاهره، ولا نشبهه، وكل ما تخيل في الذهن فالله على خلافه؛ لأن التخيل فرع الرؤية أو المثيل وهي منتفية.\n\n## المحور الثالث: العلو والاستواء\n\nالاستواء على العرش في سبعة مواضع، ومعناه إذا عدي بعلى: العلو والارتفاع والصعود والاستقرار. وتفسيره باستولى باطل لغة. وفي السماء أي على السماء كفي جذوع النخل، أو السماء بمعنى العلو. وحديث الجارية: أين الله؟ في السماء. أعتقها فإنها مؤمنة، فالسؤال مشروع والإقرار حجة إيمان. وحديث حصين يدل على الفطرة.\n\n## المحور الرابع: قاعدة مالك\n\nالاستواء غير مجهول أي معلوم المعنى، والكيف غير معقول أي لا تدركه العقول، والإيمان به واجب لوجود النص، والسؤال عن الكيفية بدعة لم يسأل عنها الصحابة. وأمر بإخراج السائل زجرا. وتطبق على كل الصفات: الرد على المعطلة بالإثبات، وعلى المشبهة بنفي الكيف، وعلى المفوضة بأن المعنى غير مجهول.\n\n## خلاصة\n\nالسنة حجة، والسياق يفضح التأويل، والتخيل عاجز، والعلو ثابت، وقاعدة مالك حاكمة.","evidences":[{"type":"sunnah","text":"ينزل ربنا كل ليلة إلى سماء الدنيا حين يبقى ثلث الليل فيقول من يدعوني فأستجيب له","reference":"متفق عليه - يبطل تأويل الأمر"},{"type":"sunnah","text":"يعجب ربك من شاب ليست له صبوة","reference":"رواه أحمد"},{"type":"sunnah","text":"يضحك الله إلى رجلين يقتل أحدهما الآخر يدخلان الجنة","reference":"متفق عليه"},{"type":"quran","text":"الرحمن على العرش استوى","reference":"سورة طه: 5 - في سبعة مواضع"},{"type":"quran","text":"أأمنتم من في السماء","reference":"سورة الملك: 16 - أي على السماء"},{"type":"sunnah","text":"أين الله؟ قالت في السماء قال أعتقها فإنها مؤمنة","reference":"رواه مسلم - مشروعية السؤال"}],"scholars":[],"benefits":["السنة مصدر مستقل.","السياق يبطل التحريف.","التخيل عاجز.","العلو بالكتاب والسنة والفطرة.","قاعدة مالك لكل الصفات."],"terms":[{"term":"المتواتر","definition":"ما رواه جمع يستحيل تواطؤهم."},{"term":"الاستواء","definition":"العلو والارتفاع إذا عدي بعلى."},{"term":"في السماء","definition":"على السماء أو في العلو."},{"term":"الكيف غير معقول","definition":"لا تدركه العقول."}],"mindMap":{"title":"الأحاديث والعلو","branches":[{"title":"الأحاديث","items":["النزول","العجب","الضحك"]},{"title":"الضوابط","items":["إثبات","لا تأويل","لا تخيل"]},{"title":"العلو","items":["استوى","في السماء","الجارية"]},{"title":"مالك","items":["معلوم","مجهول الكيف","واجب وبدعة"]}]},"summaryTable":{"headers":["القاعدة","المعنى","الرد"],"rows":[["الاستواء معلوم","العلو","على المعطلة"],["الكيف مجهول","لا تدركه العقول","على المشبهة"],["الإيمان واجب","لوجود النص","إيجاب"],["السؤال بدعة","لم يسأل الصحابة","زجر"]]},"video":{"url":"https://www.youtube.com/watch?v=pgGduSdIpKY&list=PL_SRzub3Wl-Q3dEASEFnqURn7f8pevIEL","title":"شرح لمعة الاعتقاد - ٨- شرح ( ذكر بعض أحاديث الصفات ) فضيلة الشيخ عبدالرزاق البدر حفظه الله"}},"questions":[{"q":"كيف يبطل تمام الحديث تأويل الأمر؟","options":["لا يبطل","لأن الأمر لا يقول من يدعوني فأستجيب","لأنه طويل","لا حديث"],"answer":1},{"q":"ما معنى في السماء؟","options":["داخلها","على السماء أو في العلو","لا معنى","في الأرض"],"answer":1},{"q":"كيف ترد قاعدة مالك على الثلاث؟","options":["لا ترد","على المعطلة بالإثبات والمشبهة بنفي الكيف والمفوضة بمعلومية المعنى","على واحد فقط","تؤيدهم"],"answer":1},{"q":"لماذا السؤال بأين الله مشروع؟","options":["لأنه بدعة","لأن النبي سأله وأقر الجواب وحكم بالإيمان","لأنه ممتع","لا سبب"],"answer":1}]},{"id":"lum-09","order":9,"title":"الدرس 9: صفة الكلام والرد على النفاة - درس أكاديمي","chapter":"الصفات","summary":"درس أكاديمي: منزلة الكلام، قديم النوع حادث الآحاد، مراتب السماع وأقسام الوحي، دحض خلق القرآن، وإثبات الصوت والنداء.","content":{"objectives":["استيعاب منزلة صفة الكلام وإفرادها.","التمييز بين قديم النوع وحادث الآحاد.","استقراء أدلة الكلام والنداء والصوت.","دحض خلق القرآن وضبط الإسرائيليات."],"matn":"قال ابن قدامة:\n\nومن صفات الله أنه متكلم بكلام قديم يسمعه من شاء من خلقه، سمعه موسى منه بلا واسطة وسمعه جبريل ومن أذن له من ملائكته. وأنه يكلم المؤمنين في الآخرة ويكلمونه ويأذن لهم فيزورونه.\n\nقال تعالى: {وكلم الله موسى تكليما} [النساء: 164] {يا موسى إني اصطفيتك برسالاتي وبكلامي} {منهم من كلم الله} {وما كان لبشر أن يكلمه الله إلا وحيا أو من وراء حجاب} {فلما أتاها نودي يا موسى إني أنا ربك} {إنني أنا الله لا إله إلا أنا فاعبدني}؛ وغير جائز أن يقول هذا غير الله.\n\nوقال ابن مسعود: إذا تكلم الله بالوحي سمع صوته أهل السماء. وروى ابن أنيس مرفوعا: يحشر الله الخلائق عراة حفاة غرلا بهما فيناديهم بصوت يسمعه من بعد كما يسمعه من قرب: أنا الملك أنا الديان.\n\n[المصدر: نص المستخدم + الشاملة 11366/65]","briefExplanation":"الكلام ذاتية فعلية: قديم النوع متجدد الآحاد، يسمع على مراتب، وبرهان إنني أنا الله يبطل الخلق، والصوت ثابت والوحي ثلاثة أقسام.","detailedExplanation":"## المنزلة\n\nأفردت لعظمها وارتباطها بالقرآن والوحي وشدة الخلاف فيها حتى سمي العلم علم الكلام. ومذهب السلف: يتكلم متى شاء بما شاء بصوت وحرف يليق به.\n\n## قديم النوع حادث الآحاد\n\nإطلاق قديم دون تفصيل فيه نظر. والصواب: قديم الجنس لم يزل متكلما، متجدد الآحاد يتكلم شيئا بعد شيء كالتوراة ثم الإنجيل ثم القرآن. الدليل: ما يأتيهم من ذكر من ربهم محدث إلا استمعوه.\n\n## المراتب والأقسام\n\nيسمعه الأنبياء مباشرة كموسى، والملائكة كجبريل ثم ينزل به، والمؤمنون في الآخرة. وأقسام الوحي من الشورى: وحيا في القلب، أو من وراء حجاب، أو بإرسال رسول ملك.\n\n## دحض الخلق\n\nزعموا خلقه في الشجرة. ويبطله: إنني أنا الله لا إله إلا أنا فاعبدني؛ فلا يقوله مخلوق. وتأكيده بالمصدر تكليما يبطل المجاز في اللسان.\n\n## الصوت والنداء\n\nإذا تكلم بالوحي سمع صوته أهل السماء. وينادي بصوت يسمعه من بعد كما من قرب: أنا الملك. والنداء لا يكون إلا بصوت. وبهما أي ليس معهم متاع. والفصل بالحسنات.\n\n## الإسرائيليات\n\nأثر موسى والنار من الإسرائيليات غير المرفوع، وفيه تكلف، وفي الصحيح غنية. فالاعتقاد من الوحي المعصوم.\n\n## خلاصة\n\nذاتية فعلية، بحرف وصوت، وأدلة محكمة تبطل الخلق، ووحي ثلاثة، ونقد الإسرائيليات واجب.","evidences":[{"type":"quran","text":"وكلم الله موسى تكليما","reference":"سورة النساء: 164 - التأكيد بالمصدر يبطل المجاز"},{"type":"quran","text":"إنني أنا الله لا إله إلا أنا فاعبدني","reference":"سورة طه: 14 - لا يقوله مخلوق"},{"type":"quran","text":"ما يأتيهم من ذكر من ربهم محدث إلا استمعوه","reference":"سورة الأنبياء: 2 - تجدد الآحاد"},{"type":"quran","text":"وما كان لبشر أن يكلمه الله إلا وحيا أو من وراء حجاب أو يرسل رسولا","reference":"سورة الشورى: 51 - أقسام الوحي"},{"type":"sunnah","text":"يحشر الله الخلائق عراة حفاة غرلا بهما فيناديهم بصوت يسمعه من بعد كما يسمعه من قرب أنا الملك أنا الديان","reference":"حديث ابن أنيس - إثبات الصوت"}],"scholars":[],"benefits":["الكلام شرف الوحي.","التفصيل يدفع الإطلاق الموهم.","البرهان المحكم يبطل البدعة.","الصوت ثابت لغة وشرعا.","النقد يحمي العقيدة."],"terms":[{"term":"قديم النوع","definition":"لم يزل متكلما."},{"term":"حادث الآحاد","definition":"يتكلم شيئا بعد شيء."},{"term":"التكليم","definition":"المخاطبة المؤكدة بالمصدر."},{"term":"بهما","definition":"لا متاع معهم."}],"mindMap":{"title":"صفة الكلام","branches":[{"title":"المنزلة","items":["الوحي","الفتنة","السلف"]},{"title":"التحرير","items":["قديم النوع","حادث الآحاد","محدث"]},{"title":"السماع","items":["الأنبياء","الملائكة","المؤمنون"]},{"title":"الرد","items":["إنني أنا الله","تكليما","الصوت"]}]},"summaryTable":{"headers":["المسألة","التحرير","الدليل"],"rows":[["القدم","نوع قديم وآحاد حادثة","ذكر محدث"],["السماع","مراتب ثلاثة","سمعه موسى وجبريل"],["الخلق","باطل","لا يقوله مخلوق"],["الصوت","ثابت","ينادي بصوت"]]},"video":{"url":"https://www.youtube.com/watch?v=nlSQAOqB8s0&list=PL_SRzub3Wl-Q3dEASEFnqURn7f8pevIEL","title":"شرح لمعة الاعتقاد - ٩- شرح ( من صفات الله تعالى الكلام ) فضيلة الشيخ عبدالرزاق البدر حفظه الله"}},"questions":[{"q":"ما وجه الاستدراك على قديم؟","options":["لا استدراك","إطلاقه دون تفصيل والصواب قديم النوع حادث الآحاد","نفيه","إثباته مطلقا"],"answer":1},{"q":"ما دلالة تكليما؟","options":["المجاز","التأكيد بالمصدر يبطل المجاز ويثبت الحقيقة","التكرار","لا دلالة"],"answer":1},{"q":"كيف نبطل خلق الكلام في الشجرة؟","options":["بالسكوت","بإنني أنا الله لا يقوله مخلوق فيلزم أنه كلام الله","بالشعر","لا يبطل"],"answer":1},{"q":"ما موقفنا من الإسرائيليات؟","options":["نبني عليها","لا يحتج بها وفي الصحيح غنية","نصدقها مطلقا","نكذبها مطلقا"],"answer":1}]},{"id":"lum-10","order":10,"title":"الدرس 10: القرآن كلام الله غير مخلوق - درس أكاديمي","chapter":"الصفات","summary":"درس أكاديمي: أوصاف القرآن، منه بدأ وإليه يعود، إضافته لقائله ابتداء، والتحدي والحروف وآثار الصحابة والإجماع.","content":{"objectives":["استيعاب أوصاف القرآن وختميته.","تحليل منه بدأ وإليه يعود ودحض المعنى النفسي.","تطبيق قاعدة الإضافة ابتداء لا أداء.","استقراء التحدي والحروف والإجماع على الحرف."],"matn":"قال ابن قدامة:\n\nومن كلام الله: القرآن العظيم، كتاب الله المبين وحبله المتين وصراطه المستقيم وتنزيل رب العالمين، نزل به الروح الأمين على قلب سيد المرسلين بلسان عربي مبين. منزل غير مخلوق منه بدأ وإليه يعود. وهو سور محكمات وآيات بينات وحروف وكلمات، من قرأه فأعربه فله بكل حرف عشر حسنات. له أول وآخر وأجزاء وأبعاض، متلو بالألسنة محفوظ في الصدور مسموع بالآذان مكتوب في المصاحف. فيه محكم ومتشابه وناسخ ومنسوخ وخاص وعام وأمر ونهي. {لا يأتيه الباطل من بين يديه ولا من خلفه تنزيل من حكيم حميد} [فصلت: 42].\n\n[المصدر: نص المستخدم + الشاملة 11366/72]","briefExplanation":"القرآن خاتم الكتب، منزل غير مخلوق، يضاف لقائله ابتداء، والتحدي والحروف والإجماع تثبت لفظه.","detailedExplanation":"## أوصافه\n\nخاتم الكتب كما نبينا خاتم الرسل. كتاب مبين للحق، حبل متين من تمسك نجا، صراط مستقيم، تنزيل رب العالمين تكلم به وسمعه جبريل ونزل بلسان عربي.\n\n## منه بدأ وإليه يعود\n\nمنه بدأ أي الله تكلم به ابتداء بحرف وصوت، رد على من زعم خلقه في غيره. وإليه يعود أي يرفع آخر الزمان من الصدور والسطور فلا تبقى آية. وبدعة المعنى النفسي تزعم أن العربي عبارة عن معنى قائم بالنفس، ويبطله أن القرآن بدأ من الله لفظا.\n\n## الإضافة ابتداء\n\nمتلو بالألسنة محفوظ في الصدور مسموع مكتوب. والكلام يضاف لقائله ابتداء لا لناقله أداء. فصوت القارئ ومداد الكاتب مخلوق، والمقروء والمكتوب كلام الله غير مخلوق.\n\n## التحدي والحروف\n\nقالوا إن هذا إلا قول البشر فرد بسقر، وما علمناه الشعر. فالرد على اللفظ والحروف. ولا يعقل التحدي بغير معقول: فأتوا بسورة من مثله. وافتتاح 29 سورة بكهيعص وحم والم صريح أنه حروف. وفي الحديث: من قرأه فأعربه فله بكل حرف عشر حسنات. وحديث: يقيمون حروفه إقامة السهم لا يجاوز تراقيهم يتعجلون أجره؛ أي تجويد ظاهر بلا خشوع وطلب دنيا.\n\n## الآثار والإجماع\n\nإعراب القرآن أحب إلينا من حفظ بعض حروفه أي إبانته والعمل به. ومن كفر بحرف منه فقد كفر به كله. وأجمعوا على عدد سوره وآياته وحروفه، ومن جحد حرفا متفقا فكافر. ولو لم يكن حروفا لما انطبق الكفر على الحرف.\n\n## خلاصة\n\nمنزل غير مخلوق، بحروف تكلم بها، أينما وجد فهو كلامه، وجحده كفر.","evidences":[{"type":"quran","text":"لا يأتيه الباطل من بين يديه ولا من خلفه تنزيل من حكيم حميد","reference":"سورة فصلت: 42"},{"type":"quran","text":"فأتوا بسورة من مثله","reference":"سورة البقرة: 23 - التحدي بالألفاظ"},{"type":"quran","text":"إن هذا إلا قول البشر","reference":"سورة المدثر: 25 - رد الله بسقر"},{"type":"sunnah","text":"من قرأ القرآن فأعربه فله بكل حرف عشر حسنات","reference":"إثبات الحروف"},{"type":"athar","text":"من كفر بحرف منه فقد كفر به كله","reference":"قول علي"}],"scholars":[],"benefits":["القرآن خاتم منزل.","منه بدأ يبطل النفسية.","الإضافة تحفظ اللفظ.","التحدي برهان عقلي.","جحد الحرف كفر."],"terms":[{"term":"منه بدأ","definition":"تكلم به ابتداء."},{"term":"إليه يعود","definition":"يرفع آخر الزمان."},{"term":"المعنى النفسي","definition":"بدعة نفي اللفظ."},{"term":"ابتداء","definition":"النسبة للقائل الأول."}],"mindMap":{"title":"القرآن","branches":[{"title":"أوصافه","items":["مبين","متين","مستقيم"]},{"title":"القاعدة","items":["منه بدأ","إليه يعود","غير مخلوق"]},{"title":"الإضافة","items":["متلو","محفوظ","مكتوب"]},{"title":"البراهين","items":["التحدي","الحروف","الإجماع"]}]},"summaryTable":{"headers":["المسألة","التحرير","الدليل"],"rows":[["منه بدأ","تكلم به ابتداء","رد النفسية"],["الإضافة","لقائله ابتداء","متلو محفوظ"],["التحدي","بالألفاظ","فأتوا بسورة"],["الجحد","كفر","حرف متفق"]]},"video":{"url":"https://www.youtube.com/watch?v=NgdIcMtPTPg&list=PL_SRzub3Wl-Q3dEASEFnqURn7f8pevIEL","title":"شرح لمعة الاعتقاد - ١٠- شرح ( القرآن كلام الله ) فضيلة الشيخ عبدالرزاق البدر حفظه الله"}},"questions":[{"q":"ما معنى منه بدأ وإليه يعود؟","options":["خلقه غيره ويرجع لهم","تكلم به ابتداء ويرفع آخر الزمان","لا معنى","شعر"],"answer":1},{"q":"كيف نرد أن المصحف مخلوق؟","options":["بالسكوت","الكلام يضاف لقائله ابتداء لا لناقله أداء","بالتأويل","لا رد"],"answer":1},{"q":"كيف يبطل التحدي والحروف النفسية؟","options":["لا يبطل","التحدي بالألفاظ والحروف المقطعة لا بمعنى باطن","بالشعر","بالسكوت"],"answer":1},{"q":"ما الانحراف في حديث إقامة السهم؟","options":["التجويد","تجويد ظاهر بلا خشوع وطلب دنيا","ترك القراءة","الحفظ"],"answer":1}]},{"id":"lum-11","order":11,"title":"الدرس 11: رؤية المؤمنين لربهم - درس أكاديمي","chapter":"اليوم الآخر","summary":"درس أكاديمي: منزلة الرؤية، ضوابطها الخمسة، تحليل ناضرة وناظرة وتعدية النظر، ودليل الحجب وقاعدة تشبيه الرؤية.","content":{"objectives":["استيعاب منزلة الرؤية كأعظم نعيم.","تحرير ضوابطها: بالأبصار للمؤمنين في الآخرة مع الزيارة والتكليم.","تفكيك ناضرة وناظرة وتعدية النظر ودليل الحجب.","تطبيق قاعدة تشبيه الرؤية بالرؤية."],"matn":"قال ابن قدامة:\n\nوالمؤمنون يرون ربهم في الآخرة بأبصارهم ويزورونه ويكلمهم ويكلمونه. قال تعالى: {وجوه يومئذ ناضرة إلى ربها ناظرة} [القيامة: 22-23]. وقال: {كلا إنهم عن ربهم يومئذ لمحجوبون} [المطففين: 15]، فلما حجب أولئك في السخط دل على أن المؤمنين يرونه في الرضا وإلا لم يكن بينهما فرق. وقال النبي: إنكم سترون ربكم كما ترون هذا القمر لا تضامون في رؤيته. متفق عليه. وهذا تشبيه للرؤية بالرؤية لا للمرئي بالمرئي؛ فإن الله لا شبيه له ولا نظير.\n\n[المصدر: نص المستخدم + الشاملة 11366/81]","briefExplanation":"الرؤية أعظم نعيم وهي الزيادة، بضوابط خمسة، ولغة النظر بإلى تفيد العين، والحجب دليل المخالفة، والتشبيه للوضوح لا للذات.","detailedExplanation":"## المنزلة\n\nرؤية الله الغاية والنعيم الأكمل. نعيم بدني بالأكل والقصور، ونعيم روحي أعظم برؤيته وهي الزيادة. وفي الحديث: إذا دخل أهل الجنة يقول تريدون شيئا أزيدكم... فيكشف الحجاب فما أعطوا أحب من النظر إلى ربهم. رواه مسلم.\n\n## الضوابط الخمسة\n\nبالأبصار حقيقة لا معرفة قلبية ردا على النفاة. وخاصة بالمؤمنين تشريفا. وفي الآخرة لا الدنيا: لن تروا ربكم حتى تموتوا رواه مسلم. والزيارة والمجاورة في دار الكرامة. والتكليم بلا واسطة.\n\n## تحليل القيامة\n\nناضرة بالضاد من النضرة والحسن، وناظرة بالظاء من النظر والبصر باصرة لربها مسندة للوجه. واستعمالات نظر: مجردا بمعنى الانتظار كانظرونا نقتبس، ومعدى بفي بمعنى التفكر أولم ينظروا في ملكوت، ومعدى بإلى بمعنى المعاينة إلى ربها ناظرة. فمع الوجه وإلى لا يحتمل إلا رؤية العين.\n\n## دليل الحجب\n\nكلا إنهم عن ربهم لمحجوبون. فالحجب عقوبة للكفار في السخط، فيثبت للمؤمنين في الرضا، وإلا لم يكن فرق. وهو مفهوم المخالفة عند الشافعي.\n\n## الحديث والقاعدة\n\nسترمون ربكم كما ترون القمر لا تضامون. لا تضامون أي لا تزدحمون ولا يلحقكم ضيم. والقاعدة: تشبيه الرؤية بالرؤية في الوضوح لا المرئي بالمرئي؛ فالله ليس كمثله شيء. والغاية تقريب الجلاء لا تشبيه الذات.\n\n## خلاصة\n\nبالأبصار للمؤمنين في الآخرة، ولغة بإلى صريحة، والحجب دليل، والتشبيه للوضوح.","evidences":[{"type":"quran","text":"وجوه يومئذ ناضرة إلى ربها ناظرة","reference":"سورة القيامة: 22-23 - بإلى للعين"},{"type":"quran","text":"كلا إنهم عن ربهم يومئذ لمحجوبون","reference":"سورة المطففين: 15 - مفهوم المخالفة"},{"type":"sunnah","text":"إنكم سترون ربكم كما ترون هذا القمر لا تضامون في رؤيته","reference":"متفق عليه - تشبيه الرؤية"},{"type":"sunnah","text":"فيكشف الحجاب فما أعطوا شيئا أحب إليهم من النظر إلى ربهم","reference":"رواه مسلم - الزيادة"}],"scholars":[],"benefits":["الرؤية أعظم نعيم.","بالأبصار لا بالقلب فقط.","بإلى تفيد العين.","الحجب دليل الإكرام.","التشبيه للوضوح لا للذات."],"terms":[{"term":"ناضرة","definition":"حسنة من النضارة بالضاد."},{"term":"ناظرة","definition":"باصرة بالظاء مع إلى."},{"term":"الحجب","definition":"المنع عقوبة للكفار."},{"term":"لا تضامون","definition":"لا زحام ولا ضيم."}],"mindMap":{"title":"الرؤية","branches":[{"title":"المنزلة","items":["أعظم نعيم","الزيادة","كشف الحجاب"]},{"title":"الضوابط","items":["بالأبصار","للمؤمنين","في الآخرة"]},{"title":"اللغة","items":["ناضرة وناظرة","بإلى للعين","الحجب مخالف"]},{"title":"الحديث","items":["القمر","لا تضامون","الرؤية بالرؤية"]}]},"summaryTable":{"headers":["الدليل","الوجه","النتيجة"],"rows":[["إلى ربها ناظرة","بإلى للوجه","رؤية العين"],["لمحجوبون","عقوبة الكفار","إكرام المؤمنين"],["كما ترون القمر","وضوح","لا تشبيه ذات"],["الزيادة","كشف الحجاب","أحب النعيم"]]},"video":{"url":"https://www.youtube.com/watch?v=-0RFZVPwPVQ&list=PL_SRzub3Wl-Q3dEASEFnqURn7f8pevIEL","title":"شرح لمعة الاعتقاد - ١١- شرح ( رؤية المؤمنون لربهم يوم القيامة ) فضيلة الشيخ عبدالرزاق البدر حفظه الله"}},"questions":[{"q":"ما الفرق بين ناضرة وناظرة؟","options":["لا فرق","ناضرة حسن وناظرة باصرة لربها","عكسهما","كلاهما انتظار"],"answer":1},{"q":"كيف استدل بالحجب؟","options":["لا دلالة","حجب الكفار عقوبة فيثبت رؤية المؤمنين وإلا لا فرق","إثبات الحجب للكل","نفي الرؤية"],"answer":1},{"q":"كيف نرد دعوى الانتظار والتفكر؟","options":["نقبلها","المجرد للانتظار وبفي للتفكر وبإلى مع الوجه للعين حتما","لا لغة","كلها رؤية"],"answer":1},{"q":"ما معنى تشبيه الرؤية بالرؤية؟","options":["تشبيه الله بالقمر","تشبيه الوضوح لا الذات فالله لا مثل له","لا تشبيه","تشبيه المرئي"],"answer":1}]},{"id":"lum-12","order":12,"title":"الدرس 12: القضاء والقدر - درس أكاديمي","chapter":"القدر","summary":"درس أكاديمي: علاقة القدر بالصفات، مراتبه الأربع، منزلته، والاحتجاج به ومشيئة العبد.","content":{"objectives":["توضيح علاقة القدر بصفات الله.","تعداد مراتب القدر الأربع بالأدلة.","تحديد موقعه ضمن أركان الإيمان.","تفنيد الاحتجاج به وتمييز المشيئتين."],"matn":"قال ابن قدامة:\n\nومن صفات الله أنه الفعال لما يريد، لا يكون شيء إلا بإرادته ولا يخرج عن مشيئته، وليس في العالم شيء يخرج عن تقديره. أراد ما العالم فاعلوه ولو عصمهم لما خالفوه. خلق الخلق وأفعالهم وقدر أرزاقهم وآجالهم، يهدي من يشاء بحكمته ويضل من يشاء بعدله.\n\nولا نجعل قضاء الله وقدره حجة لنا في ترك أوامره، بل لله علينا الحجة بإنزال الكتب وبعثة الرسل. وما أمر ونهى إلا المستطيع، ولم يجبر أحدا على معصية ولا اضطره لترك طاعة.\n\n[المصدر: نص المستخدم + الشاملة 11366/84]","briefExplanation":"القدر قدرة الله، بمراتب أربع، ركن سادس، لا حجة به في المعايب، ومشيئة العبد تابعة.","detailedExplanation":"## علاقته بالصفات\n\nإيراده ضمن الصفات لأن القدر قدرة الله: علمه وقدرته ومشيئته وتدبيره. قال أحمد: القدر قدرة الله.\n\n## المراتب الأربع\n\nالعلم الأزلي الشامل، ثم الكتابة في اللوح قبل السماوات والأرض، ثم المشيئة فما شاء كان، ثم الخلق حتى أفعال العباد.\n\n## المنزلة\n\nركن سادس في حديث جبريل: وأن تؤمن بالقدر خيره وشره. وإن لم يذكر في آية البر فهو داخل في الإيمان بالله. وفي القنوت: وقني شر ما قضيت.\n\n## الاحتجاج والتكليف\n\nلا حجة بالقدر: رسلا مبشرين ومنذرين لئلا يكون للناس على الله حجة بعد الرسل. والتكليف بالوسع: لا يكلف الله نفسا إلا وسعها، فاتقوا الله ما استطعتم. وللعبد مشيئة: لمن شاء منكم أن يستقيم، تابعة: وما تشاءون إلا أن يشاء الله. والأمر: اعملوا فكل ميسر، واحرص على ما ينفعك.\n\n## خلاصة\n\nتوحيد ربوبية، لا تعارض بين المشيئتين، يهدي بحكمة ويضل بعدل، ويستدل به في المصائب لا المعايب.","evidences":[{"type":"quran","text":"إنا كل شيء خلقناه بقدر","reference":"سورة القمر: 49"},{"type":"quran","text":"رسلا مبشرين ومنذرين لئلا يكون للناس على الله حجة بعد الرسل","reference":"سورة النساء: 165 - انقطاع الحجة"},{"type":"quran","text":"لا يكلف الله نفسا إلا وسعها","reference":"سورة البقرة: 286"},{"type":"quran","text":"لمن شاء منكم أن يستقيم وما تشاءون إلا أن يشاء الله رب العالمين","reference":"سورة التكوير: 28-29 - الجمع"},{"type":"sunnah","text":"وأن تؤمن بالقدر خيره وشره","reference":"حديث جبريل - الركن السادس"}],"scholars":[],"benefits":["القدر من الصفات.","المراتب تحفظ الإيمان.","لا حجة في المعايب.","المشيئة تابعة لا جبر."],"terms":[{"term":"القدر","definition":"قدرة الله علما وكتابة ومشيئة وخلقا."},{"term":"اللوح","definition":"كتبت فيه المقادير."},{"term":"الاحتجاج","definition":"الاعتذار بالقدر على المعصية باطل."},{"term":"الكسب","definition":"فعل العبد بمشيئته التابعة."}],"mindMap":{"title":"القدر","branches":[{"title":"العلاقة","items":["قدرة الله","فعلية","ربوبية"]},{"title":"المراتب","items":["علم","كتابة","مشيئة وخلق"]},{"title":"الحجة","items":["الرسل تقطعها","بالوسع","لا جبر"]},{"title":"المشيئة","items":["للعبد","تابعة","اعملوا"]}]},"summaryTable":{"headers":["المرتبة","المعنى","الدليل"],"rows":[["العلم","أزلي شامل","يعلم ما كان"],["الكتابة","في اللوح","قبل الخلق"],["المشيئة","ما شاء كان","فعال لما يريد"],["الخلق","حتى الأفعال","خلق الخلق وأفعالهم"]]},"video":{"url":"https://www.youtube.com/watch?v=kmfHJmA1P1k&list=PL_SRzub3Wl-Q3dEASEFnqURn7f8pevIEL","title":"شرح لمعة الاعتقاد - ١٢- شرح ( القضاء والقدر ) فضيلة الشيخ عبدالرزاق البدر حفظه الله"}},"questions":[{"q":"لماذا أورد القدر ضمن الصفات؟","options":["لا علاقة","لأنه قدرة الله وعلمه ومشيئته","حشو","خطأ"],"answer":1},{"q":"ما مراتب القدر؟","options":["2","علم كتابة مشيئة خلق","صلاة صوم","لا مراتب"],"answer":1},{"q":"ما موقف المحتج بالقدر على المعصية؟","options":["صحيح","باطل لانقطاع الحجة بالرسل والتكليف بالوسع","واجب","مستحب"],"answer":1},{"q":"كيف نجمع بين المشيئتين؟","options":["لا جمع","للعبد مشيئة تابعة لمشيئة الله","جبر محض","تفويض"],"answer":1}]},{"id":"lum-13","order":13,"title":"الدرس 13: الإيمان حقيقة شرعية وأركانه - درس أكاديمي","chapter":"الإيمان","summary":"درس أكاديمي: الحقيقة الشرعية، الأركان الثلاثة، الزيادة والنقصان، وتحليل الأدلة الأربعة.","content":{"objectives":["توضيح الحقيقة الشرعية وتميزها عن اللغوية.","تعداد أركان الإيمان: اعتقاد وقول وعمل.","الاستدلال على الزيادة والنقصان والتفاضل.","تحليل آية البينة وشعب الإيمان والشفاعة."],"matn":"قال ابن قدامة:\n\nوالإيمان قول باللسان وعمل بالأركان وعقد بالجنان، يزيد بالطاعة وينقص بالعصيان. قال تعالى: {وما أمروا إلا ليعبدوا الله مخلصين له الدين حنفاء ويقيموا الصلاة ويؤتوا الزكاة وذلك دين القيمة} [البينة: 5]، فجعل العبادة والإخلاص والصلاة والزكاة كله من الدين. وقال النبي: الإيمان بضع وسبعون شعبة أعلاها شهادة أن لا إله إلا الله وأدناها إماطة الأذى عن الطريق. فجعل القول والعمل من الإيمان. وقال: {فزادتهم إيمانا} {ليزدادوا إيمانا}. وقال: يخرج من النار من قال لا إله إلا الله وفي قلبه مثقال ذرة من الإيمان، فجعله متفاضلا.\n\n[المصدر: نص المستخدم + الشاملة 11366/93]","briefExplanation":"الإيمان منظومة: قول القلب وعمله، وقول اللسان، وعمل الجوارح، يزيد وينقص ويتفاضل.","detailedExplanation":"## الحقيقة الشرعية\n\nالإيمان اسم شرعي يحدده الوحي لا اللغة وحدها. وسؤال وفد عبد القيس: أتدرون ما الإيمان؟ قالوا الله ورسوله أعلم، ففسره بأعمال ظاهرة وباطنة: الشهادة والصلاة والزكاة والخمس. وقوله: ما كنت تدري ما الكتاب ولا الإيمان ولكن جعلناه نورا.\n\n## الأركان\n\nعقد بالجنان: قول القلب تصديقه، وعمل القلب نيته ومحبته وخوفه. وقول باللسان: الشهادتان والذكر والأمر. وعمل بالأركان: الصلاة والحج والجهاد وإماطة الأذى.\n\n## الزيادة والنقصان\n\nيزيد بالطاعة وينقص بالمعصية والغفلة. والعباد متفاضلون: المؤمن القوي خير من الضعيف. والزيادة تستلزم النقص عقلا وشرعا.\n\n## تحليل الأدلة\n\nالبينة جمعت الإخلاص والصلاة والزكاة وسمتها الدين. وشعب الإيمان قسمت قولا أعلاه وعملا أدناه وقلبا حياء. وفزادتهم وليزدادوا تصريح بالزيادة. والشفاعة بمثقال ذرة دليل التفاضل.\n\n## خلاصة\n\nمركب لا صلب، والعمل جزء، والشرعي مقدم على اللغوي.","evidences":[{"type":"quran","text":"وما أمروا إلا ليعبدوا الله مخلصين له الدين حنفاء ويقيموا الصلاة ويؤتوا الزكاة وذلك دين القيمة","reference":"سورة البينة: 5 - جمع الدين"},{"type":"sunnah","text":"الإيمان بضع وسبعون شعبة أعلاها شهادة أن لا إله إلا الله وأدناها إماطة الأذى","reference":"رواه مسلم - تركيب"},{"type":"quran","text":"فزادتهم إيمانا","reference":"سورة التوبة: 124 - الزيادة"},{"type":"sunnah","text":"يخرج من النار من قال لا إله إلا الله وفي قلبه مثقال ذرة من الإيمان","reference":"حديث الشفاعة - التفاضل"}],"scholars":[],"benefits":["الشرعي مقدم.","الأركان ثلاثة.","الزيادة تستلزم النقص.","الشعب دليل التركيب."],"terms":[{"term":"الحقيقة الشرعية","definition":"ما بينه الوحي."},{"term":"عقد الجنان","definition":"قول القلب وعمله."},{"term":"الشعبة","definition":"الخصلة من الإيمان."},{"term":"التفاضل","definition":"تفاوت المقدار."}],"mindMap":{"title":"الإيمان","branches":[{"title":"الحقيقة","items":["شرعية","وفد عبد القيس","نور"]},{"title":"الأركان","items":["جنان","لسان","أركان"]},{"title":"التغير","items":["يزيد","ينقص","يتفاضل"]},{"title":"الأدلة","items":["البينة","الشعب","الشفاعة"]}]},"summaryTable":{"headers":["الدليل","النوع","الوجه"],"rows":[["البينة 5","قرآن","جمع الدين"],["بضع وسبعون","حديث","قول وعمل"],["فزادتهم","قرآن","الزيادة"],["مثقال ذرة","حديث","التفاضل"]]},"video":{"url":"https://www.youtube.com/watch?v=I2tc7hMB5CY&list=PL_SRzub3Wl-Q3dEASEFnqURn7f8pevIEL","title":"شرح لمعة الاعتقاد - ١٣- شرح ( الإيمان قول وعمل ) فضيلة الشيخ عبدالرزاق البدر حفظه الله"}},"questions":[{"q":"لماذا الإيمان حقيقة شرعية؟","options":["لغة فقط","لأن الوحي بينه بأعمال كما لوفد عبد القيس","عرف فقط","لا دليل"],"answer":1},{"q":"ما أركان الإيمان؟","options":["قول فقط","اعتقاد وقول وعمل","مال","جاه"],"answer":1},{"q":"كيف تدل الزيادة على النقص؟","options":["لا تدل","كل قابل للزيادة يتطرق له النقص","عكسه","لا علاقة"],"answer":1},{"q":"ما وجه حديث الشعب؟","options":["لا وجه","قسم قولا أعلاه وعملا أدناه فالعمل منه","نفي العمل","خاص بالقلب"],"answer":1}]},{"id":"lum-14","order":14,"title":"الدرس 14: الإيمان بالغيب واليوم الآخر - درس أكاديمي","chapter":"اليوم الآخر","summary":"درس أكاديمي: قاعدة التلقي، الإسراء وموسى وملك الموت، مراحل اليوم الآخر، والشفاعة والخلود.","content":{"objectives":["توضيح الغيب كأصل ومقياس التسليم.","استنباط منهج التلقي دون اعتراض.","تحليل الإسراء وقصة موسى.","تعداد مراحل اليوم الآخر والشفاعة والخلود."],"matn":"قال ابن قدامة:\n\nويجب الإيمان بكل ما أخبر به النبي وصح به النقل عنه فيما شاهدناه أو غاب عنا نعلم أنه حق وصدق. ومن ذلك حديث الإسراء والمعراج وأنه كان يقظة لا مناما. ومن ذلك قصة ملك الموت مع موسى. ومن ذلك أشراط الساعة كالدجال ونزول عيسى ويأجوج والدابة وطلوع الشمس. وعذاب القبر ونعيمه حق وفتنته حق والبعث والحشر والحساب والميزان والصراط والحوض والشفاعة. والجنة والنار مخلوقتان لا تفنيان أبدا، ويؤتى بالموت في صورة كبش أملح فيذبح بين الجنة والنار.\n\n[المصدر: نص المستخدم + الشاملة 11366/96 وما بعدها]","briefExplanation":"الخبر الصحيح يوجب القبول، والغيب لا يقاس بالشهادة، ومراحل المعاد تثمر الاستعداد.","detailedExplanation":"## أصل الغيب وقاعدة التلقي\n\nالإيمان بالغيب محك الإيمان؛ فالمشاهد يستوي فيه الكل، والتفاضل بالتسليم. والقاعدة: ثبوت النقل ثم التسليم المطلق كمنهج الصديق: إن كان قال فقد صدق. فتقديم النص على العقل بلا تكييف.\n\n## الإسراء وموسى\n\nالإسراء يقظة بالروح والجسد؛ ولو كان مناما لما أنكرت قريش. وقصة موسى: أرسل الملك في صورة رجل غريب دخل بلا إذن فدافعه حماية لبيته وهو لا يعلمه، فلما عاد بالآية عرفه واستسلم.\n\n## المراحل\n\nبرزخ: فتنة وعذاب ونعيم على الروح والبدن. ثم بعث بنفخ وحشر حفاة عراة غرلا بهما أي بلا متاع. ثم حساب بتطاير الصحف وميزان بكفتين ولسان وشفاعة عظمى وكبائر. ثم صراط وحوض ماؤه أبيض من اللبن وخلود.\n\n## المآل\n\nالجنة والنار موجودتان مخلوقتان لا تفنيان. والشفاعة العظمى للفصل خاصة به، ولأهل الكبائر بإذن لمن ارتضى من الموحدين، والمشرك محروم: فما تنفعهم شفاعة الشافعين. وذبح الموت كبشا أملح: يا أهل الجنة خلود فلا موت، قطعا وقطع أسباب.\n\n## الأدلة\n\nالذين يؤمنون بالغيب أول المتقين. والنار يعرضون عليها غدوا وعشيا قبل الساعة دليل البرزخ. ويحشر الناس حفاة عراة غرلا لإعادة الذوات.\n\n## خلاصة\n\nقبول الخبر، وعدم قياس الغيب، والاستعداد، وخلود الدارين.","evidences":[{"type":"quran","text":"الذين يؤمنون بالغيب","reference":"سورة البقرة: 3 - أول المتقين"},{"type":"quran","text":"النار يعرضون عليها غدوا وعشيا ويوم تقوم الساعة","reference":"سورة غافر: 46 - البرزخ قبل الساعة"},{"type":"quran","text":"فما تنفعهم شفاعة الشافعين","reference":"سورة المدثر: 48 - حرمان المشرك"},{"type":"sunnah","text":"يحشر الناس يوم القيامة حفاة عراة غرلا","reference":"متفق عليه - إعادة الذوات"},{"type":"sunnah","text":"يا أهل الجنة خلود فلا موت ويا أهل النار خلود فلا موت","reference":"ذبح الموت - الخلود"}],"scholars":[],"benefits":["الغيب محك التسليم.","لا قياس للغيب بالحس.","الاستعداد ثمرة المعاد.","الخلود سرمدي."],"terms":[{"term":"الغيب","definition":"ما غاب عن الحس وثبت بالنقل."},{"term":"البرزخ","definition":"بين الموت والبعث."},{"term":"بهما","definition":"بلا متاع دنيا."},{"term":"الكبش الأملح","definition":"صورة الموت عند ذبحه."}],"mindMap":{"title":"اليوم الآخر","branches":[{"title":"التلقي","items":["ثبوت النقل","التسليم","كالصديق"]},{"title":"الدلائل","items":["الإسراء يقظة","موسى والملك","الأشراط"]},{"title":"المراحل","items":["برزخ","بعث وحشر","حساب وصراط"]},{"title":"المآل","items":["شفاعة","حوض","خلود"]}]},"summaryTable":{"headers":["المسألة","النص","الوجه"],"rows":[["التسليم","يؤمنون بالغيب","أول المتقين"],["البرزخ","يعرضون غدوا","قبل الساعة"],["الحشر","حفاة عراة","إعادة"],["الشفاعة","فما تنفعهم","للتوحيد فقط"],["الخلود","خلود فلا موت","ذبح الموت"]]},"video":{"url":"https://www.youtube.com/watch?v=iCpP2OZpPCY&list=PL_SRzub3Wl-Q3dEASEFnqURn7f8pevIEL","title":"شرح لمعة الاعتقاد - ١٤- شرح ( الإيمان بكل ما أخبر به الرسول ﷺ ) فضيلة الشيخ عبدالرزاق البدر حفظه الله"}},"questions":[{"q":"لماذا الإسراء يقظة لا مناما؟","options":["لا دليل","لأن قريشا أنكرت والمنام لا ينكر","لأنه أسهل","لا فرق"],"answer":1},{"q":"ما توجيه لطم موسى؟","options":["عصيان","دفع غريب دخل بلا إذن وهو لا يعلمه ثم استسلم بالآية","إنكار الموت","لا توجيه"],"answer":1},{"q":"ما الفرق بين الشفاعتين؟","options":["لا فرق","العظمى للفصل خاصة به والكبائر بإذن للموحدين","كلها للكفار","لا شفاعة"],"answer":1},{"q":"ما معنى ذبح الموت؟","options":["فناء الجنة","قطع الأسباب وخلود الدارين","موت جديد","لا معنى"],"answer":1}]},{"id":"lum-15","order":15,"title":"الدرس 15: حقوق النبي والصحابة والإمامة - درس أكاديمي","chapter":"الخاتمة","summary":"درس أكاديمي: خصائص النبي وأمته، ترتيب الفضل والخلافة، أحكام أهل القبلة والإمامة، حقوق الصحابة، والموقف من البدع.","content":{"objectives":["تبيان حقوق النبي ومقاماته ومزية أمته.","استيعاب ترتيب الفضل والخلافة بالأدلة.","تحديد ضوابط التكفير والطاعة وحرمة الخروج.","تفنيد الشبه حول الصحابة والتمييز بين الخلافين."],"matn":"قال ابن قدامة:\n\nومحمد رسول الله خاتم النبيين وسيد المرسلين... ولا يصح إيمان عبد حتى يؤمن برسالته... ولا يقضى بين الخلق إلا بشفاعته... وأمته خير الأمم... وأفضل أمته أبو بكر ثم عمر ثم عثمان ثم علي... والخلافة بعده ثلاثون سنة آخرها خلافة علي... ولا نجزم لأحد من أهل القبلة بجنة ولا نار إلا من جزم له الرسول... ولا نكفر أحدا من أهل القبلة بذنب... والحج والجهاد ماضيان مع كل إمام بر أو فاجر... ومن السنة الترضي عن أصحاب رسول الله ومحبتهم وذكر محاسنهم والكف عما شجر بينهم... وأزواجه أمهات المؤمنين... ويجب هجر أهل البدع... وهذه الفرق كلها في النار إلا واحدة وهي ما كان على مثل ما أنا عليه اليوم وأصحابي.\n\n[المصدر: نص المستخدم + الشاملة 11366/130 وما بعدها]","briefExplanation":"خاتمية وسيادة وشفاعة، وفضل مرتب كالخلافة، وعصمة أهل القبلة، وسلامة القلب واللسان، وهجر البدع والفرقة الناجية.","detailedExplanation":"## خصائص النبي وأمته\n\nخاتم النبيين وسيد المرسلين لا يصح إيمان إلا برسالته. له المقام المحمود للفصل ولواء الحمد والحوض المورود وإمامة النبيين. وأمته خير الأمم: كنتم خير أمة، أول دخولا الجنة.\n\n## الفضل والخلافة\n\nأفضل الأمة: أبو بكر ثم عمر ثم عثمان ثم علي. بدليل قول ابن عمر كنا نقول والنبي حي فيبلغه فلا ينكره، وقول علي على المنبر. والخلافة ثلاثون سنة آخرها علي ثم ملك من معاوية. ونشهد بالجنة للعشرة ولمن عينه النبي كالحسنين.\n\n## أهل القبلة والإمامة\n\nلا نجزم بجنة ولا نار إلا بنص، ولا نكفر بذنب دون شرك ما لم يستحله. والحج والجهاد ماضيان مع كل إمام بر أو فاجر. ومن ولي واجتمع عليه أو غلب حتى استقر حرم الخروج حماية للجمعة والدماء.\n\n## الصحابة والأمهات\n\nسلامة القلب من الغل وسلامة اللسان بالثناء والترضي والاستغفار: ربنا اغفر لنا ولإخواننا. والكف عما شجر اجتهادا. وأزواجه أمهات المؤمنين أفضلهن خديجة وعائشة المبرأة؛ ومن قذفها كفر. ومعاوية خال المؤمنين وكاتب الوحي كالستر.\n\n## البدع والاجتهاد\n\nهجر أهل البدع وترك كتبهم. والفرق 73 كلها في النار إلا ما أنا عليه وأصحابي: الرافضة والجهمية والخوارج والقدرية والمرجئة والمعتزلة. أما خلاف الأئمة الأربعة في الفروع فسائغ بين أجر وأجرين: إذا حكم فاجتهد فأصاب فله أجران.\n\n## خلاصة\n\nالفضل كالخلافة، والذنب لا يكفر، والسلامة قلب ولسان، والفقهي سائغ والبدعي مذموم.","evidences":[{"type":"quran","text":"كنتم خير أمة أخرجت للناس","reference":"سورة آل عمران: 110 - خيرية الأمة"},{"type":"quran","text":"والذين جاءوا من بعدهم يقولون ربنا اغفر لنا ولإخواننا","reference":"سورة الحشر: 10 - سلامة الصدر"},{"type":"sunnah","text":"كلها في النار إلا واحدة ما أنا عليه اليوم وأصحابي","reference":"حديث الافتراق - الفرقة الناجية"},{"type":"sunnah","text":"إذا حكم الحاكم فاجتهد ثم أصاب فله أجران","reference":"متفق عليه - الاجتهاد السائغ"},{"type":"athar","text":"كنا نقول والنبي حي أفضل هذه الأمة أبو بكر ثم عمر ثم عثمان","reference":"أثر ابن عمر - الترتيب"}],"scholars":[],"benefits":["الخاتمية شرط الإيمان.","الفضل كالخلافة.","الذنب لا يكفر.","السلامة قلب ولسان.","الفقهي سائغ والبدعي خطر."],"terms":[{"term":"الخاتم","definition":"آخر النبيين."},{"term":"العشرة","definition":"المبشرون بالجنة."},{"term":"أهل القبلة","definition":"المسلمون لا يكفرون بالذنب."},{"term":"الفرقة الناجية","definition":"ما عليه النبي وأصحابه."}],"mindMap":{"title":"الخاتمة","branches":[{"title":"النبي","items":["خاتم","شفاعة","خير أمة"]},{"title":"الصحابة","items":["ترتيب الفضل","ثلاثون سنة","العشرة"]},{"title":"الأحكام","items":["لا تكفير بذنب","طاعة","لا خروج"]},{"title":"الموقف","items":["سلامة","هجر البدع","اجتهاد سائغ"]}]},"summaryTable":{"headers":["المسألة","الضابط","الدليل"],"rows":[["الفضل","كترتيب الخلافة","إقرار النبي"],["التكفير","لا بذنب","دون استحلال"],["الصحابة","سلامة قلب ولسان","اغفر لإخواننا"],["الخلاف","فقهي سائغ وبدعي مذموم","أجر وأجران مقابل النار"]]},"video":{"url":"https://www.youtube.com/watch?v=Yr73Q_V50kE&list=PL_SRzub3Wl-Q3dEASEFnqURn7f8pevIEL","title":"شرح لمعة الاعتقاد - ١٥- شرح ( محمد خاتم النبيين ) فضيلة الشيخ عبدالرزاق البدر حفظه الله"}},"questions":[{"q":"لماذا اقترن الفضل بالخلافة؟","options":["صدفة","لإقرار النبي ترتيب أبي بكر وعمر وعثمان","لا دليل","رأي"],"answer":1},{"q":"ما ضابط أهل الكبائر؟","options":["كفار مخلدون","لا يكفرون بذنب ولا يجزم لهم إلا بنص","معصومون","لا حساب"],"answer":1},{"q":"لماذا خص معاوية بالذكر؟","options":["لا سبب","خال المؤمنين وكاتب الوحي كالستر","قرابة فقط","ملك فقط"],"answer":1},{"q":"ما الفرق بين الخلافين؟","options":["لا فرق","الفقهي سائغ مأجور والبدعي في الأصول مذموم","كلاهما كفر","كلاهما واجب"],"answer":1}]},{"id":"lum-16","order":16,"title":"الدرس 16: الدليل الشامل والتلخيص المنهجي مع أسئلة الاجتياز","chapter":"الخاتمة","summary":"خارطة الأصول الخمسة، المحاور الستة، جدول الأدلة، القواعد الكبرى، وأسئلة الاجتياز العام.","content":{"objectives":["جمع أصول اللمعة الخمسة في خارطة واحدة.","تلخيص المحاور الستة والقواعد الكبرى.","مراجعة جدول الأدلة.","اجتياز الاختبار العام."],"matn":"النص الشامل الكامل كما ورد من المستخدم محفوظ حرفيا في ملف الدليل-الشامل-لمعة-الاعتقاد.md، وفيما يلي كامل المتن الدراسي للدليل.","briefExplanation":"الأصول: الصفات، القدر، الإيمان واليوم الآخر، الحقوق والإمامة، الاعتصام بالسنة.","detailedExplanation":"## 1. المقدمة والأهمية العلمية للمتن\n\nتعد رسالة لمعة الاعتقاد الهادي إلى سبيل الرشاد من المتون العقدية الموجزة والمحررة التي تلقتها الأمة بالقبول والتعليم؛ إذ جمع فيها الإمام ابن قدامة أمهات أصول العقيدة على طريقة السلف، معتمدا على النصوص القرآنية والأحاديث مع الآثار. وتولى شرحها الشيخ عبد الرزاق البدر بأسلوب ميسر يربط بين الفهم العقلي والنص الشرعي والسلوك الإيماني.\n\n## 2. الخارطة المفهومية الكبرى\n\nأصول العقيدة: 1 الأسماء والصفات: إثبات بلا تمثيل وتنزيه بلا تعطيل وإمرار النصوص. 2 القضاء والقدر: مراتب القدر 4 وانقطاع الحجة ومشيئة العبد تابعة. 3 الإيمان واليوم الآخر: حقيقة الإيمان 3 وأحداث البرزخ وأحوال القيامة. 4 الحقوق والإمامة: فضائل الصحابة وترتيب الخلافة وطاعة الولاة. 5 الاعتصام بالسنة: هجران أهل البدع وحصر النجاة بالسنة وعذر الاجتهاد الفقهي.\n\n## 3. المحاور العقدية\n\nالصفات: إثبات ما أثبته الله ورسوله بلا تحريف ولا تعطيل ولا تكييف ولا تمثيل، بقاعدة ليس كمثله شيء وهو السميع البصير. وإمرار النصوص مع الإيمان بالمعاني ورد الكيفية. وإبطال التأويل والمعطلة والمشبهة.\n\nالكلام والقرآن: القرآن كلام الله حقيقة بحرف وصوت، منزل غير مخلوق منه بدأ وإليه يعود. والعلو والاستواء بلا حلول. والرؤية يقينا كالقمر بلا تضام وهي أعظم النعيم.\n\nالقدر: قدرة الله. مراتبه: العلم الأزلي، والكتابة في اللوح، والمشيئة الشاملة، والخلق لكل شيء. ولا احتجاج بالقدر على المعاصي؛ فالحجة بالرسل والتكليف بالوسع ومشيئة العبد تابعة.\n\nالإيمان واليوم الآخر: حقيقة شرعية مركبة: عقد بالجنان وقول باللسان وعمل بالأركان، يزيد بالطاعة وينقص بالمعصية. والبرزخ فتنة وعذاب ونعيم. والأشراط: الدجال ونزول عيسى ويأجوج والدابة وطلوع الشمس. والمعاد: البعث والحشر حفاة عراة والشفاعة والحساب والصحف والميزان والحوض والصراط والشفاعة لأهل الكبائر. والدار مخلوقتان لا تفنيان ويذبح الموت كبشا أملح للخلود.\n\nالصحابة والإمامة: الترتيب أبو بكر ثم عمر ثم عثمان ثم علي كالخلافة الراشدة ثلاثين سنة. وسلامة القلوب والألسنة ونشر المحاسن والكف عما شجر. وأمهات المؤمنين وأفضلهن خديجة وعائشة، ومعاوية خال المؤمنين. والحج والجهاد مع كل إمام بر أو فاجر، وطاعة الولاة وتحريم الخروج.\n\nالاعتصام: هجر أهل البدع، والفرق 73 كلها في النار إلا ما كان على مثل ما أنا عليه اليوم وأصحابي. والخلاف الفقهي بين الأئمة الأربعة سائغ بين أجر وأجرين، والبدعي مذموم.\n\n## 4. جدول الأدلة\n\n- التنزيه: ليس كمثله شيء وهو السميع البصير: نفي المماثلة مع إثبات الكمال.\n- الكلام: وكلم الله موسى تكليما: التكليم الحقيقي.\n- الرؤية: وجوه يومئذ ناضرة إلى ربها ناظرة: النظر بالأبصار.\n- الحجة: رسلا مبشرين ومنذرين لئلا يكون للناس حجة: قطع الاعتذار بالقدر.\n- الشعب: الإيمان بضع وسبعون شعبة: تركيب وقابلية للتفاضل.\n- الفضل: كنا نقول والنبي حي أفضل الأمة: إقرار الترتيب.\n- الناجية: كلها في النار إلا واحدة ما أنا عليه اليوم وأصحابي: ميزان النجاة.\n\n## 5. القواعد الكبرى\n\nالتلقي من الكتاب والسنة بفهم السلف. والسلامة في الصفات إمرارا بلا تكييف. والتلازم في الإيمان قول وعمل وعقيدة. والوسطية في الصحابة والولاة. والاعتصام بلزوم السنة والهلاك بالافتراق.\n\n[النص الكامل المفصل من رسالة المستخدم محفوظ في ملف الدليل-الشامل-لمعة-الاعتقاد.md مع هذا التلخيص المنهجي]","evidences":[{"type":"quran","text":"ليس كمثله شيء وهو السميع البصير","reference":"الشورى: 11"},{"type":"quran","text":"وكلم الله موسى تكليما","reference":"النساء: 164"},{"type":"quran","text":"وجوه يومئذ ناضرة إلى ربها ناظرة","reference":"القيامة: 22-23"}],"scholars":[],"benefits":["خارطة تجمع الكتاب.","القواعد تعصم.","الاجتياز يقيس الإتقان."],"terms":[{"term":"الخارطة","definition":"الأصول الخمسة."},{"term":"الاجتياز","definition":"الاختبار العام."}],"mindMap":{"title":"الدليل الشامل","branches":[{"title":"الأصول","items":["صفات","قدر","إيمان ومعاد","حقوق","اعتصام"]},{"title":"القواعد","items":["تلقي","سلامة","وسطية"]}]},"summaryTable":{"headers":["المبحث","النص","الوجه"],"rows":[["التنزيه","ليس كمثله شيء","نفي وإثبات"],["الكلام","وكلم الله موسى تكليما","حقيقة"],["الرؤية","إلى ربها ناظرة","بالأبصار"],["النجاة","ما أنا عليه وأصحابي","ميزان"]]},"video":{"url":"https://www.youtube.com/playlist?list=PL_SRzub3Wl-Q3dEASEFnqURn7f8pevIEL","title":"السلسلة الكاملة - مراجعة الدليل الشامل"}},"questions":[{"q":"ما أصول اللمعة الخمسة؟","options":["صفات وقدر وإيمان ومعاد وحقوق واعتصام","صلاة فقط","نحو","تاريخ"],"answer":0},{"q":"ما قاعدة الصفات؟","options":["تعطيل","إثبات بلا تمثيل وتنزيه بلا تعطيل","تشبيه","تفويض مطلق"],"answer":1},{"q":"ما مراتب القدر؟","options":["2","علم كتابة مشيئة خلق","5","لا مراتب"],"answer":1},{"q":"ما حقيقة الإيمان؟","options":["قول فقط","قول وعمل وعقد يزيد وينقص","مال","جاه"],"answer":1},{"q":"أين الرؤية ومتى؟","options":["في الدنيا","للمؤمنين في الآخرة بالأبصار","لا رؤية","منام فقط"],"answer":1},{"q":"ما ترتيب الفضل؟","options":["عشوائي","أبو بكر ثم عمر ثم عثمان ثم علي","عكسه","لا فضل"],"answer":1},{"q":"ما الفرقة الناجية؟","options":["أي فرقة","ما أنا عليه اليوم وأصحابي","الأكثر عددا","الأحدث"],"answer":1},{"q":"ما حكم جحد حرف متفق؟","options":["مباح","كفر بإجماع","مستحب","لا حكم"],"answer":1},{"q":"هل يحتج بالقدر على المعصية؟","options":["نعم","لا لانقطاع الحجة بالرسل","أحيانا","واجب"],"answer":1},{"q":"ما الخلاف السائغ؟","options":["العقدي","الفقهي بين الأئمة بين أجر وأجرين","لا سائغ","كل خلاف كفر"],"answer":1}]}]}]}]};